/// SPEC-0048 breakable states 1 and 3: intact (IsBreakableIntact).
fn breakable_intact(s: &GameState, id: usize) -> bool {
    matches!(s.breakables.get(&id), Some(1 | 3))
}

/// SPEC-0043 956's lift readiness: 64 clear and 211 set, or all four knights free (then 211).
fn lift_ready_956(s: &mut GameState) -> bool {
    if s.flag(64) {
        return false;
    }
    if !s.flag(211) && [208, 209, 210, 623].iter().all(|&f| s.flag(f)) {
        s.set(211, true);
    }
    s.flag(211)
}

/// SPEC-0043 956 thread 3: set 9 with 248 (67 clear), 8 with 64, else 7 (region 957 + set) into
/// slot S; nothing with 248 and 67 set.
fn thread3_956(s: &GameState) -> Vec<Action> {
    let set = match (s.flag(248), s.flag(67), s.flag(64)) {
        (true, true, _) => return Vec::new(),
        (true, false, _) => 9,
        (false, _, true) => 8,
        _ => 7,
    };
    vec![Action::LoadRegion { slot: 0, region: None }, Action::LoadRegion { slot: 0, region: Some(957 + set) }]
}

/// SPEC-0041 822 CB1, the slot loader: 58 (13 with 531 set and 532 clear, else 12); 57, 56, 55
/// or none by the zone (2: 3, 2, 1, 0; 1: 7, 6, 5, 4; else 11, 10, 9, 8); region 823 + set.
fn loader_822(s: &GameState) -> Vec<Action> {
    let zone = s.word(822, 2);
    let set = if s.flag(58) {
        if s.flag(531) && !s.flag(532) { 13 } else { 12 }
    } else {
        let k = if s.flag(57) { 3 } else if s.flag(56) { 2 } else if s.flag(55) { 1 } else { 0 };
        match zone {
            2 => k,
            1 => 4 + k,
            _ => 8 + k,
        }
    };
    vec![Action::LoadRegion { slot: 0, region: Some(823 + set) }]
}

/// SPEC-0041 985's threads: CB3 (the Gnarfas fight; 281 clear at load) and CB6 (the glade fight's
/// level-state chain; 281 set). The cutscene helpers' cameras and entity animations are Medium in
/// the spec and given in order; the boss-fight tweaks, collision masks and navmesh assignments
/// are not built.
fn thread_985(s: &mut GameState) -> Vec<Action> {
    let p = 985;
    if s.word(p, 4) != 0 {
        return Vec::new();
    }
    let l = |s: &GameState, n| s.level(n);
    let mut v = Vec::new();
    let busy = |s: &mut GameState, v: &mut Vec<Action>| {
        s.set_word(p, 4, 1);
        v.push(Action::Bits { word: 4, set: 0, clear: 1 });
    };
    let cam = |track, wait| Action::PlayCamera { track, wait, end: 1, speed: 1.0 };
    let anim = |anim| Action::EntityAnim { entity: 0, anim, looped: false, wait: true };
    if s.word(p, 9) == 1 {
        let a = s.word(p, 1);
        if l(s, 0) && !l(s, 1) {
            s.queue_movie(12);
            s.set(213, true);
            s.set_level(1, true);
            v.extend([Action::MoveHero { locator: 10 }, Action::MoveEntityFree { entity: 7, locator: 12, face: true }, Action::ReturnCamera { preset: -1, release: true }, Action::Sleep { ticks: 30 }, Action::Message { line: 14 }]);
            busy(s, &mut v);
        } else if l(s, 2) && a & 1 == 0 {
            s.set(214, true);
            s.set_word(p, 1, a | 3);
            v.extend((7..=12).map(|slot| Action::StopEffect { slot }));
            v.extend([Action::DeactivateEntity { entity: 7 }, Action::DeactivateEntity { entity: 8 }]);
        } else if s.flag(214) {
            if a & 2 != 0 && !s.movies.contains(&13) {
                s.queue_movie(13);
                v.extend([
                    Action::FadeOut { seconds: FADE, wait: true },
                    Action::MoveHero { locator: 26 },
                    Action::DeactivateEntity { entity: 5 },
                    Action::ActivateEntity { entity: 6 },
                    Action::EntityAnim { entity: 6, anim: 3, looped: true, wait: false },
                    Action::ReturnCamera { preset: -1, release: true },
                    Action::FadeIn { seconds: 1.0, wait: true },
                ]);
                busy(s, &mut v);
            } else if a & 4 != 0 && !s.movies.contains(&14) {
                // The setter of flag 64; movie 14's return world eW 74 (pack 956) loaded at once.
                s.queue_movie(14);
                s.set(64, true);
                v.push(Action::ReplaceExterior { slot: 74, plane: -1 });
                busy(s, &mut v);
            }
        } else if s.word(p, 3) != 0 {
            s.set_word(p, 3, 0);
            v.extend([Action::Sleep { ticks: 1 }, Action::MoveEntityFree { entity: 7, locator: 11, face: true }, Action::EntityAnim { entity: 8, anim: 0, looped: false, wait: false }]);
        }
        return v;
    }
    let b = s.word(p, 2);
    let scene = |line_cam: &[(u16, usize)], a1: u32, a2: u32| {
        let mut v = vec![
            Action::FadeOut { seconds: FADE, wait: true },
            Action::LetterBox { on: true, seconds: 1.0, wait: false },
            Action::MoveEntity { entity: 0, locator: 27, face: true },
            Action::MoveHero { locator: 28 },
            Action::FadeIn { seconds: FADE, wait: true },
            anim(25),
            cam(31, false),
            anim(a1),
        ];
        for &(line, track) in line_cam {
            if track > 0 {
                v.push(cam(track, false));
            }
            v.push(Action::Converse { entity: 0, line });
        }
        v.extend([anim(a2), Action::LetterBox { on: false, seconds: 1.0, wait: false }, cam(29, false), Action::ReleaseEntity { entity: 0 }, Action::ReturnCamera { preset: -1, release: true }]);
        v
    };
    if !l(s, 0) && b & 1 != 0 {
        // Level state 0, which releases the boss (SPEC-0013 G1 and G9), is the opening scene's
        // last call, after the dialogue, camera 29 and the releases (SPEC-0013 Arena build guide
        // 4 and item 6); the busy word keeps the stage from rerunning meanwhile.
        v.extend([Action::LetterBox { on: true, seconds: 1.0, wait: false }, Action::MoveHero { locator: 9 }, Action::BossFight { instance: 5 }, Action::FadeIn { seconds: FADE, wait: true }, Action::HoldHero, cam(25, true), anim(25)]);
        for (line, track) in (0..=5).zip([26, 27, 28, 29, 30, 33]) {
            v.extend([cam(track, false), Action::Converse { entity: 0, line }]);
        }
        v.extend([anim(1), anim(3), anim(4), anim(2), Action::Equip { on: true }, wait(0.5), Action::LetterBox { on: false, seconds: 1.0, wait: false }, Action::ReturnCamera { preset: -1, release: true }, Action::ReleaseEntity { entity: 0 }, Action::LevelState { flag: 0, on: true }]);
        busy(s, &mut v);
    } else if l(s, 1) && !l(s, 2) {
        // Stages 1, 3 and 5: the boss waits in its stance until the scene's last call sets the
        // stage's level state (SPEC-0013 Arena build guide 4, item 3).
        v.extend(scene(&[(8, 0)], 4, 23));
        v.push(Action::LevelState { flag: 2, on: true });
        busy(s, &mut v);
    } else if l(s, 3) && !l(s, 4) {
        v.extend(scene(&[(9, 0)], 5, 23));
        v.push(Action::LevelState { flag: 4, on: true });
        busy(s, &mut v);
    } else if l(s, 5) && !l(s, 6) {
        v.extend(scene(&[(10, 0), (11, 32), (12, 26)], 6, 23));
        v.push(Action::LevelState { flag: 6, on: true });
        busy(s, &mut v);
    } else if l(s, 7) && !l(s, 8) {
        s.set(284, true);
        s.set(301, true);
        v.extend([Action::LetterBox { on: true, seconds: 1.0, wait: false }, anim(7), Action::Converse { entity: 0, line: 13 }, anim(24), Action::FadeOut { seconds: FADE, wait: true }, Action::ReturnCamera { preset: -1, release: true }]);
        v.extend((0..=4).map(|entity| Action::DeactivateEntity { entity }));
        v.extend((7..=12).map(|slot| Action::StopEffect { slot }));
        v.extend([Action::LetterBox { on: false, seconds: 1.0, wait: false }, Action::FadeIn { seconds: FADE, wait: true }, Action::LevelState { flag: 8, on: true }]);
        busy(s, &mut v);
    } else if l(s, 0) && s.flag(284) {
        if b & 2 != 0 && b & 4 == 0 {
            s.set_word(p, 2, b | 4 | 8);
        } else if b & 8 != 0 && b & 16 == 0 {
            // The end of the glade fight: item 30, flags 67, 283 and 302, movie 44 counted, and its
            // return world eW 74 (pack 956) loaded at once.
            s.set_word(p, 2, b | 16);
            for f in [67, 283, 302] {
                s.set(f, true);
            }
            s.queue_movie(44);
            v.extend([Action::GiveItem { item: 30, count: 1 }, Action::ReplaceExterior { slot: 74, plane: -1 }]);
            busy(s, &mut v);
        }
    }
    v
}

/// SPEC-0044 1174's barrier groups: their effects and object (the seventh has no trigger; group
/// g's damage trigger is taken as 30 + g).
const BARRIERS_1174: [(&[usize], Option<usize>); 7] = [(&[50, 51, 52, 53], Some(5)), (&[42, 43, 44, 45, 46, 47, 48, 49], None), (&[35, 36, 37, 38], Some(4)), (&[32, 33, 34], None), (&[39, 40], None), (&[29, 30], None), (&[22, 23], None)];

/// A barrier group raised (its effects, its object, its damage trigger) or lowered.
fn barrier_1174(s: &mut GameState, g: usize, up: bool) -> Vec<Action> {
    let (fx, obj) = BARRIERS_1174[g];
    let mut v: Vec<Action> = fx.iter().map(|&slot| if up { Action::StartEffect { slot, camera: false } } else { Action::StopEffect { slot } }).collect();
    v.extend(obj.map(|obj| if up { Action::InitObjOn { obj, end: false } } else { Action::DeactivateObj { obj } }));
    if g < 6 {
        s.set_word(1174, 10 + g as u8, up as i32);
        v.push(reg_at(30 + g as u16, if up { 30 } else { 31 }));
    }
    v
}

/// The target of a target play (SPEC-0027 Starting a play).
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum CameraTarget {
    Hero,
    Object(usize),
}

/// The first module word of a per-tick navigation table (an entry holds the mesh id plus 1, so 0
/// is the table's reset value -1).
const NAV_TABLE: usize = 150;

/// The per-tick navigation pass of 906, 956 and 986 (SPEC-0037 906; SPEC-0043 956; SPEC-0042
/// 986): each of the first n entities whose table entry is unassigned asks for its closest mesh
/// (the host's answer lands for the next tick), and each assigned one is assigned that mesh
/// every tick. DisableVillagerSocialize is left out: the villager pair is never formed on disc.
fn nav_pass(state: &GameState, pack: u32, n: usize) -> Vec<Action> {
    let mut v = Vec::new();
    for e in 0..n {
        let word = (NAV_TABLE + e) as u8;
        match state.word(pack, word) {
            0 => v.push(Action::QueryNavmesh { entity: e, word }),
            id => v.push(Action::NavmeshAssign { entity: e, mesh: id - 1 }),
        }
    }
    v
}

/// SPEC-0054 1432's fight control thread, one tick: rule 1 (flag 6: idle), rule 2 (flag 4: the
/// finale), rule 3 (flag 2 with 3 clear: the timeout ending), rule 4 (flag 0 with 1 clear: the
/// entry sequence), rule 5 (level state 11: the director) and rule 6 (11 clear, 9 set, 10 clear:
/// the fight start step). The sequences hold the thread (word 2) until their last step. Movies 78,
/// 85 and 80 are counted as played; the finale loads eW 151 in place of movie 85.
fn fight_1432(state: &mut GameState) -> Vec<Action> {
    const P: u32 = 1432;
    let b = state.word(P, 1);
    let f = |n: u32| b & 1 << n != 0;
    let set = |s: &mut GameState, n: u32| s.set_word(P, 1, s.word(P, 1) | 1 << n);
    let clear = |s: &mut GameState, n: u32| s.set_word(P, 1, s.word(P, 1) & !(1 << n));
    if state.word(P, 2) != 0 || f(6) {
        return Vec::new();
    }
    let done = |n: u32| Action::Bits { word: 1, set: 1 << n, clear: 0 };
    let release = Action::Bits { word: 2, set: 0, clear: 1 };
    if f(4) && !f(5) {
        state.set_word(P, 2, 1);
        state.timer.deactivate();
        state.set(94, true);
        state.set(365, true);
        state.queue_movie(85);
        state.blackboard.insert((2, 151), 80);
        let mut v = vec![Action::DeactivateObj { obj: 1 }];
        v.extend([0, 5, 6, 7].map(|entity| Action::DeactivateEntity { entity }));
        v.extend([Action::SwapMode { mode: 2 }, done(6), release, Action::ReplaceExterior { slot: 151, plane: -1 }]);
        return v;
    }
    if f(2) && !f(3) {
        state.set_word(P, 2, 1);
        state.timer.deactivate();
        state.queue_movie(80);
        let mut v = vec![Action::FadeOut { seconds: FADE, wait: true }];
        v.extend([0, 5, 6, 7].map(|entity| Action::DeactivateEntity { entity }));
        v.extend((0..=2).map(|obj| Action::DeactivateObj { obj }));
        v.extend([Action::SwapMode { mode: 2 }, Action::GameOver, done(3), done(6), release]);
        return v;
    }
    if f(0) && !f(1) {
        state.set_word(P, 2, 1);
        state.queue_movie(78);
        let mut v = vec![
            Action::FadeOut { seconds: FADE, wait: true },
            Action::FadeOut { seconds: 0.0, wait: true },
            Action::MoveHero { locator: 3 },
            Action::ReturnCamera { preset: -1, release: false },
            Action::MoveEntity { entity: 0, locator: 2, face: false },
            // The move's control option is taken as 1 (free control after the move; not given).
            Action::ReleaseEntity { entity: 0 },
        ];
        v.extend((0..=2).map(|obj| Action::InitObjOn { obj, end: false }));
        v.push(Action::SwitchHero { hero: 0, effects: true, flash: true });
        v.extend((18..=25).map(|slot| Action::StartEffect { slot, camera: false }));
        v.extend([
            Action::FadeIn { seconds: FADE, wait: true },
            Action::ReturnCamera { preset: -1, release: true },
            Action::Equip { on: true },
            Action::ActivateTimer { start: 180.0, limit: 0.0, up: false },
            Action::SwapMode { mode: 3 },
            Action::SetFlag { flag: 364, on: true },
            Action::LevelState { flag: 11, on: true },
            Action::LevelState { flag: 10, on: false },
            done(1),
            release,
        ]);
        return v;
    }
    if state.level(11) {
        let mut v = Vec::new();
        if state.level(16) {
            if !f(8) {
                state.set_word(P, 3, 900);
                set(state, 8);
            } else {
                let n = state.word(P, 3) - 1;
                state.set_word(P, 3, n);
                if n < 1 {
                    clear(state, 8);
                    state.set_level(16, false);
                    state.set_level(13, true);
                }
            }
            return v;
        }
        if !f(7) && state.timer.value == 0.0 {
            set(state, 2);
        }
        let swapping = state.hero.swapping;
        if f(7) && !swapping {
            if state.level(12) {
                v.extend([7, 6, 5].map(|entity| Action::ActivateEntity { entity }));
                state.set_level(12, false);
                state.set_level(14, true);
            } else if state.level(13) {
                state.set_level(13, false);
                state.set_level(15, true);
            }
            clear(state, 7);
            state.timer.running = true;
        }
        if !f(7) {
            if state.level(12) {
                if state.hero.selected == 0 && !swapping {
                    state.timer.running = false;
                    set(state, 7);
                    v.extend([Action::SwapMode { mode: 2 }, Action::SwitchHero { hero: 1, effects: true, flash: true }, Action::SwapMode { mode: 3 }]);
                }
            } else if state.level(13) && state.hero.selected == 1 && !swapping {
                state.timer.running = false;
                set(state, 7);
                v.push(Action::SwitchHero { hero: 0, effects: true, flash: true });
            }
        }
        return v;
    }
    // The fight start step (rule 6; SPEC-0054 Arena build guide A2 and open question 45): camera
    // 4 (no keys) and the fade-in without waiting, effects 3 and 4, 30 ticks, the hero moved
    // from the alcove to the hall centre (locator 1), the letterbox off, 60 ticks, the normal
    // camera (control at about tick 90).
    if f(9) && !f(10) {
        state.set_word(P, 2, 1);
        return vec![
            Action::LetterBox { on: true, seconds: 0.0, wait: false },
            Action::PlayCamera { track: 4, wait: false, end: 1, speed: 1.0 },
            Action::BossFight { instance: 13 },
            Action::FadeIn { seconds: 0.5, wait: false },
            Action::StartEffect { slot: 3, camera: false },
            Action::StartEffect { slot: 4, camera: false },
            wait(0.5),
            Action::MoveHero { locator: 1 },
            Action::LetterBox { on: false, seconds: 0.7, wait: false },
            wait(1.0),
            Action::ReturnCamera { preset: -1, release: true },
            done(10),
            release,
        ];
    }
    Vec::new()
}

/// SPEC-0054 1432's control thread B, one tick: walks entities 7, 6 and 5. An entry goes ahead with
/// level state 11, flag 6 and level state 12 clear and Roberta active, and when its marker is set
/// only if its Grunt is dead. It waits 480 ticks and, if 12 is still clear and Roberta still
/// active, places the Grunt at locator 4 and sets the marker. Words: 4 the entry, 5 the wait, 6 to
/// 8 the markers. The entity is activated before the move: a forced bind reads the record at once
/// here, and the move would find nothing to place before it.
fn grunts_1432(state: &mut GameState) -> Vec<Action> {
    const P: u32 = 1432;
    const ENTRIES: [usize; 3] = [7, 6, 5];
    let mut v = Vec::new();
    let mut k = state.word(P, 4) as usize;
    let n = state.word(P, 5);
    if n > 0 {
        state.set_word(P, 5, n - 1);
        if n > 1 {
            return v;
        }
        if !state.level(12) && state.hero.selected == 1 {
            v.extend([Action::ActivateEntity { entity: ENTRIES[k] }, Action::MoveEntityAir { entity: ENTRIES[k], locator: 4 }]);
            state.set_word(P, 6 + k as u8, 1);
        }
        k += 1;
    }
    while k < ENTRIES.len() {
        let open = state.level(11) && state.word(P, 1) & 1 << 6 == 0 && !state.level(12) && state.hero.selected == 1;
        if open && (state.word(P, 6 + k as u8) == 0 || state.entity_dead(ENTRIES[k])) {
            state.set_word(P, 4, k as i32);
            state.set_word(P, 5, 480);
            return v;
        }
        k += 1;
    }
    state.set_word(P, 4, 0);
    v
}

/// A draw of Random(lo, hi) for the modules whose routines make several in one tick: the host's
/// raw value for this tick (`trigger_raw`), stirred by a running count (word 40).
fn draw(s: &mut GameState, pack: u32, lo: i32, hi: i32) -> i32 {
    let k = s.word(pack, 40) as u32;
    s.set_word(pack, 40, k.wrapping_add(1) as i32);
    let raw = s.trigger_raw.wrapping_add(k.wrapping_mul(2_654_435_761));
    lo + ((raw >> 8) % (hi - lo + 1) as u32) as i32
}

/// SPEC-0044 722 odds: three distinct values from 1 to 4 (words 10 to 12) and their sum (13).
fn odds_722(s: &mut GameState) {
    let mut odds: [i32; 3] = [0; 3];
    for i in 0..3 {
        let mut v = draw(s, 722, 1, 4);
        while odds[..i].contains(&v) {
            v = draw(s, 722, 1, 4);
        }
        odds[i] = v;
        s.set_word(722, 10 + i as u8, v);
    }
    s.set_word(722, 13, odds.iter().sum());
}

/// SPEC-0044 722 dialogue routines R0 to R7; each group is a three-line cycle.
fn talk_722(routine: u8, s: &mut GameState) -> Vec<Action> {
    let three = |a: u16| [a, a + 1, a + 2];
    let f76 = s.flag(76);
    match routine {
        0 => {
            let on = s.flag(562);
            cycle_in(s, 722, 0, on as i32, &three(if on { 0 } else { 6 }))
        }
        1 if s.flag(562) => cycle_in(s, 722, 1, 0, &three(9)),
        1 if s.flag(561) => cycle_in(s, 722, 1, 1, &three(15)),
        1 if f76 => {
            s.set(561, true);
            vec![Action::Talk { line: 18 }]
        }
        1 => cycle_in(s, 722, 1, 2, &three(19)),
        2 => cycle_in(s, 722, 2, 0, &three(22)),
        3 => cycle_in(s, 722, 3, 0, &three(31)),
        4 => cycle_in(s, 722, 4, f76 as i32, &three(if f76 { 34 } else { 37 })),
        5 => cycle_in(s, 722, 5, 0, &three(47)),
        6 => cycle_in(s, 722, 6, f76 as i32, &three(if f76 { 50 } else { 53 })),
        7 => cycle_in(s, 722, 7, f76 as i32, &three(if f76 { 56 } else { 59 })),
        _ => Vec::new(),
    }
}

/// SPEC-0044 722 race thread (Medium), one tick. Words: 20 the phase (1 asked for, 2 running), 21
/// busy, 22 to 24 the steps, 25 the last pick, 26 the cameras played, 27 the hero's pick. The
/// entities' viewing points and entity 15's six reset locators are not given (R-0181): they stay
/// where they stand, and 15 is released where it is.
fn race_722(s: &mut GameState) -> Vec<Action> {
    let p = 722;
    if s.word(p, 21) != 0 {
        return Vec::new();
    }
    let camera = |track| Action::PlayCamera { track, wait: false, end: 1, speed: 1.0 };
    let idle = Action::Bits { word: 21, set: 0, clear: 1 };
    match s.word(p, 20) {
        1 => {
            s.set_word(p, 20, 2);
            s.set_word(p, 21, 1);
            for k in 22..=24 {
                s.set_word(p, k, 0);
            }
            s.set_word(p, 25, -1);
            s.set_word(p, 26, 0);
            let mut table = crate::entityctl::Table::default();
            let mut v = vec![Action::HoldHero, Action::FadeOut { seconds: 0.7, wait: true }];
            v.extend((0..3).map(|e| Action::MoveEntity { entity: e, locator: e + 1, face: true }));
            v.extend([Action::MoveHero { locator: 4 }, Action::HeroAnim { anim: 0, wait: false }]);
            // R-0181: the spectators are placed on their viewing locators under the black screen.
            for (e, locator) in [(11, 5), (12, 6), (14, 8), (13, 7), (15, 10)] {
                v.push(Action::MoveEntity { entity: e, locator, face: true });
                table.add(e, 36, (4.0, 7.0), (3.0, 4.0));
                table.add_anim(e, 37, 2.5);
                v.push(Action::EntityAnim { entity: e, anim: 36, looped: true, wait: false });
            }
            v.push(Action::AiBehavior { entity: 15, code: 0 });
            s.entity_tables.insert(p, table);
            v.extend([Action::FadeIn { seconds: 0.7, wait: false }, camera(4), wait(4.5), Action::FadeOut { seconds: 0.7, wait: true }, Action::FadeIn { seconds: 0.7, wait: true }, camera(5), idle]);
            v
        }
        2 => {
            let last = s.word(p, 25);
            let mut r = draw(s, p, 0, 2);
            if r == last && draw(s, p, 1, 3) <= s.word(p, 10 + r as u8) {
                r = draw(s, p, 0, 2);
            }
            s.set_word(p, 25, r);
            let sum = s.word(p, 13);
            if draw(s, p, 1, sum) <= s.word(p, 10 + r as u8) {
                return Vec::new();
            }
            let steps = s.word(p, 22 + r as u8) + 1;
            s.set_word(p, 22 + r as u8, steps);
            s.set_word(p, 21, 1);
            let mut v = vec![Action::EntityAnim { entity: r as usize, anim: 2, looped: false, wait: true }];
            let played = s.word(p, 26);
            if let Some((track, _)) = [(6, 5), (7, 10), (8, 14)].into_iter().enumerate().map(|(k, (t, at))| (t, (k as i32, at))).find(|&(_, (k, at))| k == played && steps >= at) {
                s.set_word(p, 26, played + 1);
                v.push(camera(track));
            }
            if steps >= 16 {
                let won = s.word(p, 27) == r;
                let prize = s.word(p, 10 + r as u8) as u32;
                s.set_word(p, 20, 0);
                s.entity_tables.insert(p, crate::entityctl::Table::default());
                v.extend([Action::ReturnCamera { preset: -1, release: true }, Action::Message { line: 71 + r as u16 }, Action::FadeOut { seconds: 0.7, wait: true }]);
                v.extend([(11, 56), (12, 55), (13, 58), (14, 57)].map(|(entity, locator)| Action::MoveEntity { entity, locator, face: true }));
                // Entity 15 goes to one of locators 20 to 25 and wanders again.
                let locator = 20 + draw(s, p, 0, 5) as usize;
                v.extend([Action::MoveEntity { entity: 15, locator, face: true }, Action::AiBehavior { entity: 15, code: 6 }, Action::ReleaseEntity { entity: 15 }]);
                v.extend((0..3).map(|e| Action::MoveEntity { entity: e, locator: e + 1, face: true }));
                v.push(Action::FadeIn { seconds: 0.7, wait: false });
                if won {
                    v.push(Action::GiveItem { item: 139, count: prize });
                }
                odds_722(s);
            }
            v.push(idle);
            v
        }
        _ => Vec::new(),
    }
}

/// The on-enter lines of the small interiors (SPEC-0041 859, SPEC-0042 1005, SPEC-0043 748, 1008,
/// 1011, 1014, 1020, SPEC-0039 1131 and 1172), in entity 0's conversation frame where the spec
/// brackets them. 1131's routine is also Init's thread 2; here it runs once on arrival. A
/// counter word 3.
fn enter_interior(pack: u32, s: &mut GameState) -> Vec<Action> {
    let f = |s: &GameState, n| s.flag(n);
    let say = |line| vec![Action::Converse { entity: 0, line }];
    let turn = |s: &mut GameState, a: u16, n: i32| {
        let c = s.word(pack, 3).rem_euclid(n);
        s.set_word(pack, 3, (c + 1) % n);
        vec![Action::Converse { entity: 0, line: a + c as u16 }]
    };
    match pack {
        748 => {
            if (f(s, 406) || f(s, 407)) && s.word(pack, 4) == 0 {
                s.set_word(pack, 4, 1);
                s.set_word(pack, 3, 0);
            }
            let a = if f(s, 406) || f(s, 407) { 0 } else if f(s, 405) { 2 } else if f(s, 76) { 4 } else { 6 };
            turn(s, a, 2)
        }
        859 => say(if f(s, 48) { 0 } else if f(s, 47) { 2 } else if f(s, 507) { 4 } else if f(s, 506) { 6 } else { 8 }),
        1005 | 1011 | 1020 => say(if f(s, 86) { 0 } else { 3 }),
        1008 => {
            let case = f(s, 86) as i32 + 1;
            if s.word(pack, 4) != case {
                s.set_word(pack, 4, case);
                s.set_word(pack, 3, 0);
            }
            turn(s, if f(s, 86) { 0 } else { 3 }, 3)
        }
        1014 => {
            let line = if f(s, 580) {
                22
            } else if f(s, 578) {
                25
            } else if f(s, 86) {
                28
            } else {
                29
            };
            vec![Action::Message { line }]
        }
        1131 => {
            if f(s, 301) && s.has_item(124) {
                return say(35);
            }
            let a = if f(s, 301) { 0 } else if f(s, 216) { 2 } else if f(s, 202) { 4 } else if f(s, 150) { 6 } else { 8 };
            turn(s, a, 2)
        }
        1172 => {
            let line = if f(s, 301) { 0 } else if f(s, 216) { 2 } else if f(s, 202) { 4 } else if f(s, 150) { 6 } else if f(s, 7) { 7 } else { 8 };
            vec![Action::Message { line }]
        }
        _ => Vec::new(),
    }
}

/// SPEC-0039 thread 2 of 1136, 1140, 1143 and 1172: one line on arrival, the first line of the first
/// matching branch (the counters start at 0 on every entry). 1172's has no talk partner.
fn arrival_line(pack: u32, s: &GameState) -> Vec<Action> {
    let f = |n| s.flag(n);
    let line = match pack {
        1136 => [(f(301), 0), (f(216), 2), (f(491) && !f(492), 4), (f(490) && !f(491), 5), (f(202), 7), (f(150), 9), (f(7), 11)].iter().find(|c| c.0).map(|c| c.1),
        1140 => [(f(301), 36), (f(216), 1), (f(481) && !f(483), 3), (f(202), 5), (f(150), 7), (f(7), 9)].iter().find(|c| c.0).map(|c| c.1),
        1143 => [(f(301), 0), (f(216), 2), (f(386) && !f(387), 4), (f(202), 6), (f(150), 8), (f(7), 10)].iter().find(|c| c.0).map(|c| c.1),
        _ => [(f(301), 0), (f(216), 2), (f(202), 4), (f(150), 6), (f(7), 8)].iter().find(|c| c.0).map(|c| c.1),
    };
    let Some(line) = line else { return Vec::new() };
    let entity = if matches!(pack, 1136 | 1143) && f(10) { 1 } else { 0 };
    if pack == 1172 {
        vec![Action::WaitLoads, Action::Message { line }]
    } else {
        vec![Action::WaitLoads, Action::Converse { entity, line }]
    }
}

/// The proximity routines of the small interiors. "Pattern C" is the ordinary line rotation (R-0182).
fn talk_interior(pack: u32, routine: u8, s: &mut GameState) -> Vec<Action> {
    let three = |a: u16| [a, a + 1, a + 2];
    let talk = |line| vec![Action::Talk { line }];
    let f = |s: &GameState, n| s.flag(n);
    match pack {
        // SPEC-0037 776: with Roberta active a draw of 1 takes the cycle; else the flag's line and
        // the counter (word 1) goes to 1.
        776 => {
            if s.hero.selected == 1 && draw(s, pack, 1, 3) == 1 {
                let c = s.word(pack, 1);
                s.set_word(pack, 1, if c == 0 { 1 } else if c == 1 { 2 } else { 0 });
                return talk(match c {
                    0 => 14,
                    1 => 15,
                    _ => 16,
                });
            }
            s.set_word(pack, 1, 1);
            talk(if f(s, 68) { 8 } else { 11 })
        }
        // SPEC-0043 748 routine 2: one counter (word 1), set to 0 once on the first visit with 407.
        748 => {
            let turn = |s: &mut GameState, a: u16| {
                let c = s.word(pack, 1).rem_euclid(3);
                s.set_word(pack, 1, (c + 1) % 3);
                vec![Action::Talk { line: a + c as u16 }]
            };
            if f(s, 407) {
                if s.word(pack, 2) == 0 {
                    s.set_word(pack, 2, 1);
                    s.set_word(pack, 1, 0);
                }
                turn(s, 8)
            } else if f(s, 405) {
                if s.has_item(24) {
                    s.take(24, 1);
                    s.set(407, true);
                    talk(11)
                } else {
                    turn(s, 12)
                }
            } else if f(s, 76) {
                s.set(405, true);
                talk(15)
            } else {
                turn(s, 16)
            }
        }
        // SPEC-0041 859 handler P: the line, then the twelve-item count, whose line 13 replaces it.
        859 => {
            let chosen = if f(s, 423) && !f(s, 424) {
                s.set(424, true);
                talk(14)
            } else if f(s, 48) {
                cycle_in(s, pack, 0, 0, &three(17))
            } else if f(s, 47) {
                cycle_in(s, pack, 0, 1, &three(10))
            } else if f(s, 507) {
                cycle_in(s, pack, 0, 2, &three(27))
            } else if f(s, 506) {
                cycle_in(s, pack, 0, 3, &three(30))
            } else {
                s.set(506, true);
                talk(33)
            };
            if f(s, 506) && !f(s, 507) && (160..=171).all(|i| s.has_item(i)) {
                s.set(507, true);
                return vec![Action::LoadRegion { slot: 0, region: None }, Action::LoadRegion { slot: 0, region: Some(860) }, Action::Talk { line: 13 }];
            }
            chosen
        }
        // SPEC-0042 1005 handler P.
        1005 => {
            let on = f(s, 86);
            cycle_in(s, pack, 0, on as i32, &three(if on { 10 } else { 13 }))
        }
        // SPEC-0043 1008, 1011 and 1020.
        1008 => talk(if f(s, 86) { 12 } else { 15 }),
        1011 | 1020 => talk(if f(s, 86) { 10 } else { 13 }),
        // SPEC-0043 1014 routines 1 and 2 (Josh: 86 set with 578 and 580 clear starts the Pink
        // Posies row).
        1014 if routine == 1 => {
            if f(s, 86) && !f(s, 578) && !f(s, 580) {
                s.set(578, true);
            }
            talk(if f(s, 86) { 16 } else { 19 })
        }
        1014 => {
            if f(s, 580) {
                talk(1)
            } else if f(s, 578) && f(s, 579) {
                s.items.remove(&83);
                s.set(580, true);
                talk(3)
            } else if f(s, 578) {
                talk(4)
            } else {
                talk(if f(s, 86) { 7 } else { 10 })
            }
        }
        // SPEC-0039 1131 handler 3.
        1131 => {
            if f(s, 301) && s.has_item(124) {
                return talk(36);
            }
            let (case, a) = if f(s, 301) { (0, 20) } else if f(s, 216) { (1, 23) } else if f(s, 202) { (2, 26) } else if f(s, 150) { (3, 29) } else { (4, 32) };
            cycle_in(s, pack, 0, case, &three(a))
        }
        // SPEC-0039 1136 handler 3.
        1136 => {
            if f(s, 301) {
                cycle_in(s, pack, 0, 0, &three(13))
            } else if f(s, 216) {
                cycle_in(s, pack, 0, 1, &three(16))
            } else if f(s, 492) {
                if f(s, 202) {
                    cycle_in(s, pack, 0, 2, &three(19))
                } else if f(s, 150) {
                    cycle_in(s, pack, 0, 3, &three(22))
                } else if f(s, 7) {
                    cycle_in(s, pack, 0, 4, &three(25))
                } else {
                    Vec::new()
                }
            } else if !f(s, 490) {
                s.set(490, true);
                talk(32)
            } else if f(s, 491) {
                s.set(492, true);
                s.take(70, 5);
                talk(28)
            } else {
                cycle_in(s, pack, 0, 5, &three(29))
            }
        }
        // SPEC-0039 1140 handler 3 (R-0182).
        1140 => {
            if f(s, 499) {
                cycle_in(s, pack, 0, 0, &three(16))
            } else if f(s, 301) {
                cycle_in(s, pack, 0, 1, &[38, 36, 36])
            } else if f(s, 216) {
                cycle_in(s, pack, 0, 2, &three(19))
            } else if f(s, 483) {
                if f(s, 202) {
                    cycle_in(s, pack, 0, 3, &three(22))
                } else if f(s, 150) {
                    cycle_in(s, pack, 0, 4, &three(25))
                } else if f(s, 7) {
                    cycle_in(s, pack, 0, 5, &three(28))
                } else {
                    Vec::new()
                }
            } else if !f(s, 481) {
                s.set(481, true);
                talk(35)
            } else if s.has_item(69) {
                s.set(483, true);
                s.take(69, 1);
                talk(31)
            } else {
                cycle_in(s, pack, 0, 6, &three(32))
            }
        }
        // SPEC-0039 1143 handler 3 (R-0182).
        1143 => {
            if f(s, 301) {
                cycle_in(s, pack, 0, 0, &three(12))
            } else if f(s, 216) {
                cycle_in(s, pack, 0, 1, &three(15))
            } else if f(s, 387) {
                if f(s, 202) {
                    cycle_in(s, pack, 0, 2, &three(18))
                } else if f(s, 150) {
                    cycle_in(s, pack, 0, 3, &three(21))
                } else if f(s, 7) {
                    cycle_in(s, pack, 0, 4, &three(24))
                } else {
                    Vec::new()
                }
            } else if !f(s, 386) {
                s.set(386, true);
                talk(31)
            } else if s.has_item(2) {
                s.set(387, true);
                s.take(2, 1);
                talk(27)
            } else {
                cycle_in(s, pack, 0, 5, &three(28))
            }
        }
        // SPEC-0039 1172 handler 3 (R-0182).
        1172 => {
            if f(s, 301) {
                cycle_in(s, pack, 0, 0, &three(10))
            } else if f(s, 216) {
                cycle_in(s, pack, 0, 1, &three(13))
            } else if !f(s, 136) {
                talk(28)
            } else if f(s, 202) {
                cycle_in(s, pack, 0, 2, &three(16))
            } else if f(s, 193) {
                cycle_in(s, pack, 0, 3, &three(19))
            } else if f(s, 150) {
                cycle_in(s, pack, 0, 4, &three(22))
            } else {
                cycle_in(s, pack, 0, 5, &three(25))
            }
        }
        _ => Vec::new(),
    }
}

/// SPEC-0043 and SPEC-0042: the type-2 value for eW 81 of the Market Town interiors.
fn market_value(pack: u32) -> Option<i32> {
    match pack {
        1005 => Some(10),
        1008 => Some(20),
        1011 => Some(30),
        1014 => Some(40),
        1020 => Some(70),
        _ => None,
    }
}

/// SPEC-0044 1174's floor tile i (36 to 53): solid object, pieces, the piece that stays (long) or
/// the fallen object (short), whether it is short, its sound (id, time) and its fade start.
fn tile_1174(i: u16) -> (usize, std::ops::RangeInclusive<usize>, usize, bool, (i32, f32), f32) {
    let late = i >= 46;
    let long = |s: usize| {
        let sound = (8, if i == 53 { 0.05 } else if late { 0.55 } else { 0.85 });
        (s, s + 1..=s + 11, s + 1, false, sound, if late { 1.0 } else { 0.9 })
    };
    match i {
        36..=41 => long(37 + 12 * (i as usize - 36)),
        42 => (109, 110..=118, 119, true, (7, 0.9), 1.1),
        43 => (120, 121..=131, 132, true, (7, 2.25), 1.1),
        44 | 45 => long(133 + 12 * (i as usize - 44)),
        46 => (157, 158..=166, 167, true, (8, 0.05), 1.0),
        47..=52 => long(168 + 12 * (i as usize - 47)),
        _ => (240, 26..=36, 26, false, (8, 0.05), 1.0),
    }
}

/// DFS_Act1_SetTriggerData's update form (SPEC-0030 row 81).
fn act1_update(s: &mut GameState, index: u16, value: bool) {
    if let Some(p) = s.act1_map.iter_mut().find(|p| p.0 == index) {
        p.1 = value;
    }
}

/// SPEC-0044 1174 entering section k: the map holds that section's solid tiles, its two-hit object
/// (section 0) and its intact breakables (section 3).
fn section_1174(s: &mut GameState, k: usize) {
    s.set_word(1174, 180, k as i32);
    let (tiles, breakables): (std::ops::RangeInclusive<u16>, std::ops::Range<u16>) = match k {
        0 => (36..=39, 0..0),
        1 => (40..=45, 0..0),
        2 => (46..=49, 0..0),
        _ => (50..=53, 22..30),
    };
    s.act1_map.clear();
    if k == 0 {
        s.act1_map.push((5, true));
    }
    for t in tiles {
        let solid = s.word(1174, 100 + (t - 36) as u8) == 0;
        s.act1_map.push((t, solid));
    }
    for b in breakables {
        let intact = s.word(1174, 165 + (b - 22) as u8) == 0;
        s.act1_map.push((b, intact));
    }
}

/// SPEC-0042 Pack 1174 mask bits: 1 the two-hit barrier, 2 the section 3 gates, 4 tile 43.
fn mask_1174(s: &mut GameState, set: i32, clear: i32) -> Action {
    let bits = (s.word(1174, 191) | set) & !clear;
    s.set_word(1174, 191, bits);
    Action::CollisMask { mask: bits as u32 }
}

/// A tile's crumble entry (state 1 short, 3 long): the solid object off, the pieces on and played,
/// its effect and sound 7, the map entry cleared, the clock stamped.
fn tile_fire(s: &mut GameState, i: u16) -> Vec<Action> {
    let k = (i - 36) as u8;
    let (solid, pieces, fallen, short, _, _) = tile_1174(i);
    s.set_word(1174, 100 + k, if short { 1 } else { 3 });
    s.set_word(1174, 120 + k, s.hero.tick as i32);
    s.set_word(1174, 140 + k, 0);
    act1_update(s, i, false);
    let mut v = vec![Action::DeactivateObj { obj: solid }];
    if short {
        v.push(Action::DeactivateObj { obj: fallen });
    }
    for obj in pieces {
        v.extend([Action::InitObjOn { obj, end: false }, Action::PlayAnim { obj, speed: if short { 1.2 } else { 1.0 }, wait: false }]);
    }
    v.extend([Action::StartEffect { slot: 92 + k as usize, camera: false }, Action::PlaySound { cue: 7, locator: Some(73 + k as usize) }]);
    v
}

/// SPEC-0044 1174 thread W2, the floor tiles: the timed sounds and the end of each crumble (only
/// the rest piece or the fallen object stays; the fade's alpha ramp is not drawn, the pieces go at
/// its end), and the links: tile 43 adds 4 to the collision mask and stage bit 8, and drops tile 42
/// 1.7 s on; tile 53 starts the object 17 scene; tile 42 starts object 6's timer record. Then the
/// two-hit barrier's finish, the gates and thread W3.
fn tiles_1174(s: &mut GameState) -> Vec<Action> {
    let mut v = Vec::new();
    let now = s.hero.tick as i32;
    for i in 36..=53u16 {
        let k = (i - 36) as u8;
        let state = s.word(1174, 100 + k);
        if !matches!(state, 1 | 3) {
            continue;
        }
        let t = (now - s.word(1174, 120 + k)) as f32 / 60.0;
        let (_, pieces, stays, short, (cue, at), fade) = tile_1174(i);
        if t > at && s.word(1174, 140 + k) == 0 {
            s.set_word(1174, 140 + k, 1);
            v.push(Action::PlaySound { cue, locator: Some(73 + k as usize) });
            if !short {
                v.push(Action::PlaySound { cue: 7, locator: Some(73 + k as usize) });
            }
        }
        if i == 43 {
            if s.word(1174, 1) & 1 << 8 == 0 {
                s.set_word(1174, 1, s.word(1174, 1) | 1 << 8);
                v.push(mask_1174(s, 4, 0));
            }
            if t > 1.7 && s.word(1174, 100 + 6) == 0 {
                v.extend(tile_fire(s, 42));
            }
        }
        // The crumble lasts past its timed sound (the pieces are still playing then).
        if t >= (fade + 0.5).max(at + 0.02) {
            s.set_word(1174, 100 + k, state + 1);
            v.extend(pieces.filter(|&obj| obj != stays).map(|obj| Action::DeactivateObj { obj }));
            if short {
                v.push(Action::InitObjOn { obj: stays, end: false });
            }
        }
    }
    // The object 17 group: the wall object 7 goes and the pieces stay at their end poses.
    if s.word(1174, 100 + 17) != 0 && s.word(1174, 190) == 0 {
        s.set_word(1174, 190, 1);
        v.extend((17..=19).flat_map(|obj| [Action::InitObjOn { obj, end: false }, Action::PlayAnim { obj, speed: 1.0, wait: false }]));
        v.push(Action::DeactivateObj { obj: 7 });
        v.extend((15..=21).map(|slot| Action::StartEffect { slot, camera: false }));
    }
    // Tile 42's timer record: object 6 for 0.85 s, then sound 8 at locator 79.
    if s.word(1174, 100 + 6) != 0 {
        if s.word(1174, 160) == 0 {
            s.set_word(1174, 160, now);
            v.push(Action::PlayAnim { obj: 6, speed: 1.0, wait: false });
        } else if s.word(1174, 161) == 0 && now - s.word(1174, 160) > 51 {
            s.set_word(1174, 161, 1);
            v.push(Action::PlaySound { cue: 8, locator: Some(79) });
        }
    }
    // The two-hit barrier: past 2.5 s from the break (the longest piece ends at 2.133 s), stage bit
    // 17 and all four objects hidden. The alpha ramp is not drawn.
    if s.word(1174, 174) == 1 && now - s.word(1174, 175) > 150 {
        s.set_word(1174, 174, 2);
        s.set_word(1174, 1, s.word(1174, 1) | 1 << 17);
        v.extend((13..=16).map(|obj| Action::DeactivateObj { obj }));
    }
    // The section 3 gate pairs: (delay to the sound, the helper's length, gate, closed look, helper).
    for (j, (delay, ends, gate, look, helper)) in [(144, 176, 22, 23, 20), (198, 236, 24, 25, 21)].into_iter().enumerate() {
        let j = j as u8;
        if s.word(1174, 182 + j) != 1 {
            continue;
        }
        let t = now - s.word(1174, 184 + j);
        if t > delay && s.word(1174, 186 + j) == 0 {
            s.set_word(1174, 186 + j, 1);
            v.push(Action::PlaySound { cue: 9, locator: None });
        }
        if t > ends {
            s.set_word(1174, 182 + j, 2);
            v.extend([Action::DeactivateObj { obj: gate }, Action::InitObjOn { obj: look, end: false }, Action::InitObjOn { obj: helper, end: true }]);
            v.push(mask_1174(s, 2, 0));
        }
    }
    // Thread W3: more than 3.0 s since its last switch, the pending checkpoint becomes current.
    let pending = s.word(1174, 178);
    if pending != 0 && (s.word(1174, 177) == 0 || now - s.word(1174, 179) > 180) {
        let k = pending - 1;
        s.set_word(1174, 177, pending);
        s.set_word(1174, 178, 0);
        s.set_word(1174, 179, now);
        let fourth = if k < 4 { 1 } else if matches!(36 + k, 42 | 43 | 46) { 73 + k } else { -1 };
        s.act1_indices = [17 + 3 * k, 19 + 3 * k, 18 + 3 * k, fourth];
    }
    v
}

/// SPEC-0044 1174 gate pairs, a request: 1 closes (the gate and helper played from their start, bit 2
/// cleared, stamped); 0 reopens (rest look).
fn gates_1174(s: &mut GameState, close: bool) -> Vec<Action> {
    let now = s.hero.tick as i32;
    let mut v = Vec::new();
    for (j, (gate, look, helper)) in [(22, 23, 20), (24, 25, 21)].into_iter().enumerate() {
        let j = j as u8;
        s.set_word(1174, 182 + j, close as i32);
        s.set_word(1174, 184 + j, now);
        s.set_word(1174, 186 + j, 0);
        v.extend([Action::InitObjOn { obj: gate, end: false }, Action::InitObjOn { obj: helper, end: false }, Action::DeactivateObj { obj: look }]);
        if close {
            v.extend([Action::PlayAnim { obj: gate, speed: 1.0, wait: false }, Action::PlayAnim { obj: helper, speed: 1.0, wait: false }]);
        }
    }
    v.push(mask_1174(s, 0, 2));
    v
}

/// SPEC-0044 1174 thread W1, one helper a tick in the spec's order.
fn stage_1174(s: &mut GameState) -> Vec<Action> {
    let p = 1174;
    let bits = s.word(p, 1);
    let has = |b: u32| bits & (1 << b) != 0;
    let set = |s: &mut GameState, b: u32| s.set_word(p, 1, s.word(p, 1) | 1 << b);
    if s.word(p, 2) != 0 {
        return Vec::new();
    }
    let mut v = Vec::new();
    if has(0) && !has(1) {
        set(s, 1);
        v.extend([Action::FadeOut { seconds: FADE, wait: true }, Action::WaitLoads, Action::BossFight { instance: 3 }, Action::Equip { on: true }, Action::FadeIn { seconds: 0.5, wait: true }, Action::ReturnCamera { preset: -1, release: true }]);
        return v;
    }
    if !has(2) && !has(3) && !has(4) {
        if let Some(b) = [1, 2, 3].iter().position(|&l| s.level(l)) {
            set(s, 2 + b as u32);
        }
    } else if !has(5) {
        set(s, 5);
        s.set_level(4, false);
        return v;
    }
    let lvl4 = |on: bool| Action::LevelState { flag: 4, on };
    if has(8) && !has(9) {
        set(s, 9);
        s.set_word(p, 2, 1);
        v.extend([lvl4(true), Action::PlayCamera { track: 6, wait: true, end: 1, speed: 1.0 }, Action::ReturnCamera { preset: -1, release: true }, Action::DeactivateObj { obj: 8 }, lvl4(false), Action::Bits { word: 2, set: 0, clear: 1 }]);
        return v;
    }
    if has(6) && !has(7) {
        set(s, 7);
        for g in [0, 1, 6] {
            v.extend(barrier_1174(s, g, true));
        }
    } else if has(10) && !has(11) {
        set(s, 11);
        v.extend([lvl4(true), Action::HoldHero, Action::FadeOut { seconds: 0.0, wait: true }]);
        v.extend(gates_1174(s, false));
        for g in [0, 1, 6] {
            v.extend(barrier_1174(s, g, false));
        }
        v.extend([Action::LetterBox { on: true, seconds: 1.0, wait: false }, Action::MoveHero { locator: 3 }, Action::PlayCamera { track: 7, wait: false, end: 1, speed: 1.0 }, Action::FadeIn { seconds: 0.5, wait: true }, Action::WalkHero { locator: 4, wait: true, orient: false }]);
        v.extend(barrier_1174(s, 4, true));
        v.extend([Action::HeroAnim { anim: 32, wait: false }, wait(2.0)]);
        v.extend([(1, 41), (2, 42), (3, 43)].map(|(entity, locator)| Action::WalkEntity { entity, locator, wait: false, orient: false, stop: 1.1 }));
        v.extend(barrier_1174(s, 2, true));
        v.extend(barrier_1174(s, 3, true));
        v.extend([
            Action::PlayCamera { track: 8, wait: false, end: 1, speed: 1.0 },
            Action::EntityAnim { entity: 1, anim: 7, looped: false, wait: false },
            wait(0.2),
            Action::EntityAnim { entity: 3, anim: 4, looped: false, wait: false },
            wait(0.3),
            Action::EntityAnim { entity: 2, anim: 5, looped: false, wait: false },
            wait(2.0),
            Action::LetterBox { on: false, seconds: 1.0, wait: false },
            Action::MoveHero { locator: 4 },
            Action::ReturnCamera { preset: -1, release: true },
            Action::ReleaseEntity { entity: 1 },
            Action::ReleaseEntity { entity: 2 },
            Action::ReleaseEntity { entity: 3 },
            lvl4(false),
        ]);
    } else if has(12) && !has(13) {
        set(s, 13);
        v.extend([lvl4(true), Action::LetterBox { on: true, seconds: 1.0, wait: false }, Action::PlayCamera { track: 10, wait: false, end: 1, speed: 1.0 }, wait(0.3), Action::HoldHero, Action::MoveHero { locator: 5 }, Action::WalkHero { locator: 2, wait: true, orient: false }]);
        v.extend((9..=14).map(|slot| Action::StartEffect { slot, camera: false }));
        v.push(wait(0.5));
        v.extend([(1, 53), (2, 54), (3, 55)].map(|(entity, locator)| Action::WalkEntity { entity, locator, wait: false, orient: false, stop: 1.1 }));
        v.push(wait(1.0));
        for g in 0..7 {
            v.extend(barrier_1174(s, g, g == 5));
        }
        v.extend(gates_1174(s, true));
        v.extend([Action::HeroAnim { anim: 32, wait: true }]);
        v.extend((1..=3).map(|entity| Action::EntityAnim { entity, anim: 4, looped: false, wait: false }));
        v.extend([wait(0.5), wait(4.5), Action::ReturnCamera { preset: -1, release: true }, Action::LetterBox { on: false, seconds: 1.0, wait: false }, lvl4(false)]);
        v.extend((1..=3).map(|entity| Action::ReleaseEntity { entity }));
    } else {
        return v;
    }
    s.set_word(p, 2, 1);
    v.push(Action::Bits { word: 2, set: 0, clear: 1 });
    v
}

/// SPEC-0041 1428 switch k's three state effects.
const SWITCH_FX_1428: [[usize; 3]; 3] = [[2, 3, 4], [5, 6, 7], [8, 9, 10]];

/// The switches' start states (first, second, third), shown.
fn switch_start_1428(s: &mut GameState) -> Vec<Action> {
    let mut v = Vec::new();
    for k in 0..3 {
        s.set_word(1428, 40 + k as u8, k as i32);
        v.extend(SWITCH_FX_1428[k].iter().enumerate().map(|(i, &slot)| if i == k { Action::StartEffect { slot, camera: false } } else { Action::StopEffect { slot } }));
    }
    v
}

/// Switch k advanced one state (first, second, third, first), its effects swapped.
fn advance_switch_1428(s: &mut GameState, k: usize) -> Vec<Action> {
    let w = 40 + k as u8;
    let old = s.word(1428, w).rem_euclid(3) as usize;
    let new = (old + 1) % 3;
    s.set_word(1428, w, new as i32);
    vec![Action::StopEffect { slot: SWITCH_FX_1428[k][old] }, Action::StartEffect { slot: SWITCH_FX_1428[k][new], camera: false }]
}

/// SPEC-0041 1428 THREAD-A's rules and the update helper (the pulse and the shot meter H13).
fn arena_1428(s: &mut GameState) -> Vec<Action> {
    let p = 1428;
    let now = s.hero.tick as i32;
    let mut out = Vec::new();
    // The pulse: level state 2 for one tick.
    let pulse = s.word(p, 4) != 0;
    s.set_level(2, pulse);
    s.set_word(p, 4, 0);
    // H13: ten shot hits on trigger 5 within 10 s set 328.
    if s.word(p, 2) != 0 && !s.flag(328) {
        if s.shot_hits.contains(&5) {
            let slot = (0..10).min_by_key(|&i| s.word(p, 50 + i)).unwrap_or(0);
            s.set_word(p, 50 + slot, now + 1);
        }
        let live = (0..10).filter(|&i| s.word(p, 50 + i) > 0 && now + 1 - s.word(p, 50 + i) < 600).count();
        for i in 0..10 {
            if s.word(p, 50 + i) > 0 && now + 1 - s.word(p, 50 + i) >= 600 {
                s.set_word(p, 50 + i, 0);
            }
        }
        out.extend((0..10).map(|i| if i < live { Action::StartEffect { slot: 11 + i, camera: false } } else { Action::StopEffect { slot: 11 + i } }));
        if live >= 10 {
            s.set(328, true);
            s.set_word(p, 20, now + 30);
            out.extend([Action::StopEffect { slot: 1 }, Action::StartEffect { slot: 0, camera: false }]);
            out.extend(switch_start_1428(s));
        } else if live > 0 {
            out.push(Action::StartEffect { slot: 1, camera: false });
        }
    }
    let bits = s.word(p, 1);
    if bits & 1 == 0 || s.word(p, 3) != 0 {
        return out;
    }
    let busy = |s: &mut GameState, v: &mut Vec<Action>| {
        s.set_word(p, 3, 1);
        v.push(Action::Bits { word: 3, set: 0, clear: 1 });
    };
    if bits & 128 != 0 {
        // The act start (movies 56, 91, 57 and 58 counted; act 4; 333; the return world eW 178,
        // pack 1411, loaded at once). Its BossFightTweakHero is stage 1, which has no effect.
        s.set_word(p, 1, (bits & !128) | 256);
        for m in [56, 91, 57, 58] {
            s.queue_movie(m);
        }
        s.set(333, true);
        out.extend([Action::ActStart { stage: 4 }, Action::ReplaceExterior { slot: 178, plane: -1 }]);
    } else if bits & 0b11100 != 0 {
        // H15, the switch press: camera 4, the hero at locator 5 + k, hero animation 141, the
        // switch object, switch k and its linked switch advanced.
        let k = (2..5).find(|&b| bits & (1 << b) != 0).unwrap_or(2) - 2;
        s.set_word(p, 1, bits & !0b11100);
        s.set_word(p, 23, now);
        out.extend([
            Action::HoldHero,
            Action::PlayCamera { track: 4, wait: true, end: 1, speed: 1.0 },
            Action::MoveHero { locator: 5 + k },
            wait(0.3),
            Action::HeroAnim { anim: 141, wait: false },
            Action::PlayAnim { obj: k, speed: 1.0, wait: false },
        ]);
        out.extend(advance_switch_1428(s, k));
        out.extend(advance_switch_1428(s, (k + 1) % 3));
        out.extend([Action::WaitObj { obj: k }, Action::InitObjOn { obj: k, end: false }, Action::ReturnCamera { preset: -1, release: true }]);
        busy(s, &mut out);
    } else if bits & 32 != 0 && bits & 64 == 0 {
        s.set(331, true);
        s.set_word(p, 1, bits | 128);
        out.extend([Action::DeactivateEntity { entity: 1 }, Action::DeactivateEntity { entity: 0 }]);
    } else if bits & 2 == 0 {
        // The boss-room return (R-0175): under the black fade, in order: movie 55, 326, entity 1, item
        // 117 for item 116, Queen Fyora at locator 1, the Darkest Faerie at 2, the hero at 3, the
        // normal camera, the boss-fight refill of instance 12; the fade in; object 3; effects 24 to 26.
        s.set_word(p, 1, bits | 2);
        s.set(326, true);
        s.remove_all(117);
        out.extend([
            Action::FadeOut { seconds: 0.5, wait: true },
            Action::PlayFmv { movie: 55 },
            Action::ActivateEntity { entity: 1 },
            Action::GiveItem { item: 116, count: 1 },
            Action::MoveEntity { entity: 0, locator: 1, face: true },
            Action::MoveEntity { entity: 1, locator: 2, face: true },
            Action::MoveHero { locator: 3 },
            Action::ReturnCamera { preset: -1, release: true },
            Action::BossFight { instance: 12 },
            Action::FadeIn { seconds: 1.0, wait: true },
            Action::InitObjOn { obj: 3, end: false },
        ]);
        out.extend((24..=26).map(|slot| Action::StartEffect { slot, camera: false }));
    } else {
        // H17, the taunts (by 330, 329, 328, 327, none: the first three lines then the last two
        // alternating), when the delay has run out and the hero is free.
        if now >= s.word(p, 20) && !s.hero.occupied && !s.hero.swapping && s.hero.hp > 0 {
            let g = [330, 329, 328, 327].iter().position(|&f| s.flag(f)).unwrap_or(4) as u16;
            let b = 3 * g;
            let n = s.word(p, 21) + 1;
            s.set_word(p, 21, n);
            s.set_word(p, 22, now);
            s.set_word(p, 20, now + if n <= 3 { 1200 } else { 3600 });
            let talk = head_then(s, p, 1, g as i32, b, &[b + 1, b + 2]);
            out.extend(talk.into_iter().map(|a| match a {
                Action::Talk { line } => Action::Message { line },
                a => a,
            }));
        }
        // The flag 330 check: all three switches in their first state.
        if s.flag(329) && !s.flag(330) && (0..3).all(|k| s.word(p, 40 + k) == 0) {
            s.set(330, true);
            s.set_word(p, 20, now + 30);
            out.push(Action::StartEffect { slot: 0, camera: false });
        }
        // The game-over check: hero 1 dead without item 50 while 328 is clear; as Roberta swap
        // mode 1, else SetGameOver.
        if !s.flag(328) && s.hero.dead[1] && !s.has_item(50) {
            out.push(if s.hero.selected == 1 { Action::SwapMode { mode: 1 } } else { Action::GameOver });
        }
    }
    out
}

/// RegisterScriptTrigger outside Init.
fn reg_at(index: u16, routine: u8) -> Action {
    Action::RegisterTrigger { index, routine }
}

/// SPEC-0044 735's breaker groups 1 to 7: (first breakable, count, falling object, platform
/// object).
const BREAKER_735: [(usize, usize, usize, usize); 7] = [(4, 3, 59, 5), (7, 2, 60, 6), (9, 4, 61, 7), (13, 4, 62, 8), (17, 5, 63, 9), (22, 6, 64, 10), (28, 4, 65, 11)];

/// SPEC-0044 735 break scene of group k: the look-at camera of track 21 (played as its track),
/// the group's breakables made breakable and broken, sound 10, the falling object's animation
/// (waited) and the object off, effect 0, the platform object on and animated at 0.7, 30 ticks,
/// effect 0 off and the normal camera.
fn break_scene_735(k: usize) -> Vec<Action> {
    let Some(&(first, n, fall, plat)) = BREAKER_735.get(k.wrapping_sub(1)) else { return Vec::new() };
    let mut v = vec![Action::PlayCamera { track: 21, wait: false, end: 1, speed: 1.0 }];
    for id in first..first + n {
        v.extend([Action::MakeBreakable { id, on: true }, Action::Break { id }]);
    }
    v.extend([
        Action::PlaySound { cue: 10, locator: None },
        Action::PlayAnim { obj: fall, speed: 1.0, wait: true },
        Action::DeactivateObj { obj: fall },
        Action::StartEffect { slot: 0, camera: false },
        Action::InitObjOn { obj: plat, end: false },
        Action::PlayAnim { obj: plat, speed: 0.7, wait: false },
        Action::Sleep { ticks: 30 },
        Action::StopEffect { slot: 0 },
        Action::ReturnCamera { preset: -1, release: false },
    ]);
    v
}

/// SPEC-0041 1324's stage-2 plate handler (plate 1: block 3 to locator 2, camera 1, hero to
/// locator 10, mark A; plate 0: block 4 to locator 1, camera 0, hero to locator 9, mark B).
fn plate2_1324(index: u16, s: &mut GameState) -> Vec<Action> {
    let (block, locator, track, hero, word) = if index == 1 { (3, 2, 1, 10, 8) } else { (4, 1, 0, 9, 9) };
    let mut v = vec![Action::HoldHero, Action::FadeOut { seconds: 0.5, wait: true }, Action::MoveBlock { block, locator }];
    if s.word(1324, 10) == 0 {
        v.push(Action::MoveHero { locator: hero });
    }
    s.set_word(1324, word, 1);
    // Then (SPEC-0041, R-0095 answered) a fade out, the normal camera, a fade in without a wait
    // and a second normal-camera return; the live path never reaches the FMV-23 scene.
    v.extend([Action::HeroAnim { anim: 0, wait: false }, Action::FadeIn { seconds: 0.5, wait: false }, Action::PlayCamera { track, wait: true, end: 1, speed: 1.0 }, wait(1.0)]);
    v.extend([
        Action::FadeOut { seconds: 0.5, wait: true },
        Action::ReturnCamera { preset: -1, release: true },
        Action::FadeIn { seconds: 0.5, wait: false },
        Action::ReturnCamera { preset: -1, release: true },
    ]);
    v
}

/// SPEC-0044 1393 room records (R-0090, R-0105): the outer-gate pairs (even, odd), the statue
/// pair (+0x10, +0x14), the door mechanisms (+0x18 close, +0x1C open), the levers (+0x20 plate,
/// +0x24 entry), the forms (+0x28 open, +0x2C closed), the camera and the guards (entity, home
/// locator).
struct Room1393 {
    gates: [(usize, usize); 2],
    statue: (usize, usize),
    door: (usize, usize),
    plate: usize,
    entry: usize,
    forms: (usize, usize),
    camera: usize,
    guards: &'static [(usize, usize)],
}

const ROOMS_1393: [Room1393; 5] = [
    Room1393 { gates: [(48, 49), (50, 51)], statue: (0, 1), door: (26, 27), plate: 10, entry: 12, forms: (28, 29), camera: 4, guards: &[(0, 13)] },
    Room1393 { gates: [(52, 53), (54, 55)], statue: (2, 3), door: (30, 31), plate: 14, entry: 16, forms: (32, 33), camera: 5, guards: &[(1, 20)] },
    Room1393 { gates: [(56, 57), (58, 59)], statue: (4, 5), door: (34, 35), plate: 18, entry: 20, forms: (36, 37), camera: 6, guards: &[(2, 35), (3, 46)] },
    Room1393 { gates: [(60, 61), (62, 63)], statue: (6, 7), door: (38, 39), plate: 22, entry: 46, forms: (40, 41), camera: 7, guards: &[(4, 56), (5, 69), (6, 70), (7, 109)] },
    Room1393 { gates: [(64, 65), (66, 67)], statue: (8, 9), door: (42, 43), plate: 24, entry: 46, forms: (44, 45), camera: 7, guards: &[] },
];

/// 1393's module words: the opening latch, the area-active word, and per room the guard door
/// open (the constructor's state 1, closed, is 0 here), the plate latch, the gate word (1 once
/// an alarm has closed the gates, 0 at load and after an entry: the trigger-12 area word lies
/// past rooms 0 and 1, so their entries do not run on a first pass and the gates must count as
/// open from the load) and the first-alarm latch; then the thread counter.
const W1393_LATCH: u8 = 0;
const W1393_AREA: u8 = 1;
const W1393_OPEN: u8 = 10;
const W1393_PLATE: u8 = 20;
const W1393_GATE: u8 = 30;
const W1393_ALARMED: u8 = 40;
const W1393_TICK: u8 = 50;

/// The gate arrangement: `odd` activates the odd members (open), else the even ones; both
/// selected animations play at +1.0 without wait.
fn gates_1393(r: &Room1393, odd: bool) -> Vec<Action> {
    let mut v = Vec::new();
    for &(e, o) in &r.gates {
        let (on, off) = if odd { (o, e) } else { (e, o) };
        v.extend([Action::InitObjOn { obj: on, end: false }, Action::DeactivateObj { obj: off }]);
    }
    v.extend(r.gates.iter().map(|&(e, o)| Action::PlayAnim { obj: if odd { o } else { e }, speed: 1.0, wait: false }));
    v
}

/// The guard-door close: +0x18 on, +0x28 and +0x1C off, (sound 7 on an entry), +0x18 played,
/// +0x2C on; the door state becomes closed.
fn close_1393(i: usize, s: &mut GameState, sound: bool) -> Vec<Action> {
    let r = &ROOMS_1393[i];
    s.set_word(1393, W1393_OPEN + i as u8, 0);
    let mut v = vec![Action::InitObjOn { obj: r.door.0, end: false }, Action::DeactivateObj { obj: r.forms.0 }, Action::DeactivateObj { obj: r.door.1 }];
    if sound {
        v.push(Action::PlaySound { cue: 7, locator: None });
    }
    v.extend([Action::PlayAnim { obj: r.door.0, speed: 1.0, wait: false }, Action::InitObjOn { obj: r.forms.1, end: false }]);
    v
}

/// A room entry (SPEC-0044 1393): the entry lever forward at +0.75 (wait) and back at -0.75,
/// the plate lever reset at -0.6, the open gate arrangement, the door closed if open, every
/// guard reset (animation 81, off, home, on, 82 with the cloak, behaviour 6); the plate unlatches.
fn entry_1393(i: usize, s: &mut GameState) -> Vec<Action> {
    let r = &ROOMS_1393[i];
    let mut v = vec![
        Action::PlayAnim { obj: r.entry, speed: 0.75, wait: true },
        Action::PlayAnim { obj: r.entry, speed: -0.75, wait: false },
        Action::PlayAnim { obj: r.plate, speed: -0.6, wait: false },
    ];
    v.extend(gates_1393(r, true));
    if s.word(1393, W1393_OPEN + i as u8) != 0 {
        v.extend(close_1393(i, s, true));
    }
    for &(entity, locator) in r.guards {
        v.extend([
            Action::EntityAnim { entity, anim: 81, looped: false, wait: false },
            Action::DeactivateEntity { entity },
            Action::MoveEntity { entity, locator, face: true },
            Action::ActivateEntity { entity },
        ]);
        if s.cloak_worn {
            v.push(Action::EntityAnim { entity, anim: 82, looped: false, wait: false });
        }
        v.push(Action::AiBehavior { entity, code: 6 });
    }
    s.set_word(1393, W1393_GATE + i as u8, 0);
    s.set_word(1393, W1393_PLATE + i as u8, 0);
    v
}

/// A plate (SPEC-0044 1393): with the gate open and the plate unlatched, the plate lever plays;
/// a closed door opens (+0x1C on, +0x18 off, the room camera and door animation, 1 s, the open
/// form on and the closed form off, 1 s, the normal camera). The plate latches.
fn plate_1393(i: usize, s: &mut GameState) -> Vec<Action> {
    let r = &ROOMS_1393[i];
    if s.word(1393, W1393_GATE + i as u8) != 0 || s.word(1393, W1393_PLATE + i as u8) != 0 {
        return Vec::new();
    }
    s.set_word(1393, W1393_PLATE + i as u8, 1);
    let mut v = vec![Action::PlayAnim { obj: r.plate, speed: 1.0, wait: false }];
    if s.word(1393, W1393_OPEN + i as u8) == 0 {
        s.set_word(1393, W1393_OPEN + i as u8, 1);
        v.extend([
            Action::InitObjOn { obj: r.door.1, end: false },
            Action::DeactivateObj { obj: r.door.0 },
            camera(r.camera),
            Action::PlayAnim { obj: r.door.1, speed: 1.0, wait: false },
            wait(1.0),
            Action::InitObjOn { obj: r.forms.0, end: false },
            Action::DeactivateObj { obj: r.forms.1 },
            wait(1.0),
            release_camera(),
        ]);
    }
    v
}

/// A room alarm (SPEC-0044 1393). "Under the room's gate-state conditions" is taken as the
/// gates not yet closed by an alarm (since the load or the room's last entry), which also stops
/// the 10-tick thread from raising it again: sound 5, the guards aggressive and visible, the door closed if open,
/// the gate-state word cleared, the even gate arrangement, the statue pair toggled (+0x10 on and
/// played, +0x14 off), on the first alarm the room camera for 2 s, and the turn of +0x14 toward the hero
/// (its rate is not given: `ALIGN_1393`).
fn alarm_1393(i: usize, s: &mut GameState) -> Vec<Action> {
    let r = &ROOMS_1393[i];
    if s.word(1393, W1393_GATE + i as u8) != 0 {
        return Vec::new();
    }
    let mut v = vec![Action::PlaySound { cue: 5, locator: None }];
    for &(entity, _) in r.guards {
        v.extend([Action::Agro { entity }, Action::DisableInvisibility { entity }]);
    }
    if s.word(1393, W1393_OPEN + i as u8) != 0 {
        v.extend(close_1393(i, s, false));
    }
    s.set_word(1393, W1393_GATE + i as u8, 1);
    v.extend(gates_1393(r, false));
    v.extend([
        Action::InitObjOn { obj: r.statue.0, end: false },
        Action::PlayAnim { obj: r.statue.0, speed: 1.0, wait: false },
        Action::DeactivateObj { obj: r.statue.1 },
    ]);
    if s.word(1393, W1393_ALARMED + i as u8) == 0 {
        s.set_word(1393, W1393_ALARMED + i as u8, 1);
        v.extend([camera(r.camera), wait(2.0), release_camera()]);
    }
    v.push(Action::AlignObj { obj: r.statue.1, t: ALIGN_1393 });
    v
}

/// The statues' turn fraction a call: the spec names axis 2 only; pack 1246's one listed call uses 0.05.
const ALIGN_1393: f32 = 0.05;

/// SPEC-0044 1393 trigger callbacks (registered with the trigger index as the routine).
fn trigger_1393(call: TriggerCall, s: &mut GameState) -> Vec<Action> {
    let area = s.word(1393, W1393_AREA) != 0;
    match call.index {
        // Trigger 0, the opening (once per load, before the area is active). Not built: the
        // guards' patrol data (the zeroed shared record).
        0 if call.state == 1 && call.object && !area && s.word(1393, W1393_LATCH) == 0 => {
            s.set_word(1393, W1393_LATCH, 1);
            let cam = |track| Action::PlayCamera { track, wait: true, end: 1, speed: 1.0 };
            let mut v = vec![fade_out()];
            for &(entity, locator) in ROOMS_1393[0].guards {
                v.extend([Action::Agro { entity }, Action::AiBehavior { entity, code: 6 }, Action::MoveEntity { entity, locator, face: true }, Action::DeactivateEntity { entity }]);
            }
            v.extend([
                Action::MoveHero { locator: 4 },
                Action::PlayAnim { obj: 49, speed: 1.0, wait: false },
                Action::PlayAnim { obj: 51, speed: 1.0, wait: false },
                fade_in(),
                cam(8),
                cam(10),
                Action::WalkHero { locator: 5, wait: true, orient: true },
                cam(ROOMS_1393[0].camera),
                Action::InitObjOn { obj: 49, end: false },
                Action::InitObjOn { obj: 51, end: false },
                Action::DeactivateObj { obj: 48 },
                Action::DeactivateObj { obj: 50 },
                cam(9),
                release_camera(),
            ]);
            for &(entity, _) in ROOMS_1393[0].guards {
                v.push(Action::EntityAnim { entity, anim: 81, looped: false, wait: false });
                if s.cloak_worn {
                    v.push(Action::EntityAnim { entity, anim: 82, looped: false, wait: false });
                }
            }
            v.push(Action::SetFlag { flag: 697, on: true });
            v
        }
        12 if call.object => {
            s.set_word(1393, W1393_AREA, 1);
            Vec::new()
        }
        1 | 7 | 13 | 19 if call.state == 1 && call.object && area => match call.index {
            1 => entry_1393(0, s),
            7 => entry_1393(1, s),
            13 => entry_1393(2, s),
            _ => {
                let mut v = entry_1393(3, s);
                v.extend(entry_1393(4, s));
                v
            }
        },
        2 | 8 | 14 | 23 | 24 if call.state == 1 && call.object => plate_1393([2, 8, 14, 23, 24].iter().position(|&t| t == call.index).unwrap_or(0), s),
        5 | 9 | 15 | 16 | 22 if call.state == 2 && call.object => match call.index {
            5 => alarm_1393(0, s),
            9 => alarm_1393(1, s),
            15 | 16 => alarm_1393(2, s),
            _ => {
                let mut v = alarm_1393(3, s);
                v.extend(alarm_1393(4, s));
                v
            }
        },
        // Statue triggers 4, 11, 18 and 21 turn +0x14 toward the hero. Triggers 3, 10 and 17 are registered;
        // their bodies are not described.
        4 | 11 | 18 | 21 => {
            let i = match call.index {
                4 => 0,
                11 => 1,
                18 => 2,
                _ => 3,
            };
            vec![Action::AlignObj { obj: ROOMS_1393[i].statue.1, t: ALIGN_1393 }]
        }
        _ => Vec::new(),
    }
}

/// AddAnimObjSound registrations over (start, 1.0) (SPEC-0031 Call-site arguments and gates,
/// R-0111): (object, cue, start fraction).
fn obj_sounds(list: &[(usize, i32, f32)]) -> Vec<Action> {
    list.iter().map(|&(obj, cue, a)| Action::AddAnimObjSound { obj, cue, a, b: 1.0 }).collect()
}

/// SPEC-0041 1324's solved-scene helper (see the stage-1 plate callback).
/// The scene-done word is flag 239 itself here (Init and Update read the flag).
fn solved_1324() -> Vec<Action> {
    let pair = [Action::PlaySound { cue: 4, locator: None }, Action::PlaySound { cue: 5, locator: None }];
    let mut v = pair.to_vec();
    v.extend([
        wait(2.0),
        Action::SetFlag { flag: 239, on: true },
        Action::FadeOut { seconds: 2.0, wait: true },
        Action::KillSound { cue: 4, locator: None },
        Action::KillSound { cue: 5, locator: None },
        Action::PlayFmv { movie: 23 },
        Action::FadeIn { seconds: 0.5, wait: false },
    ]);
    for _ in 0..10 {
        v.extend(pair.clone());
        v.push(Action::Sleep { ticks: 15 });
    }
    v
}

/// SPEC-0041 1324's beam helper: the other beam objects (9 to 14) hidden and `beam` looped; the
/// rhythm period in seconds (None keeps the word and period; 14 with no period clears it).
fn beam_1324(s: &mut GameState, beam: usize, period: Option<f32>) -> Vec<Action> {
    let mut v: Vec<Action> = (9..=14).filter(|&o| o != beam).map(|obj| Action::DeactivateObj { obj }).collect();
    v.extend([Action::InitObjOn { obj: beam, end: false }, Action::LoopAnim { obj: beam, speed: 1.0 }]);
    match period {
        Some(p) => {
            s.set_word(1324, 1, beam as i32 + 1);
            s.set_word(1324, 6, (p * 60.0) as i32);
        }
        None if beam == 14 => s.set_word(1324, 1, 0),
        None => {}
    }
    v
}

/// SPEC-0042 1397's statues: (object, start angle in degrees).
const STATUES_1397: [(usize, i32); 4] = [(59, 0), (58, 90), (57, -180), (56, 270)];

/// SPEC-0041 1096's item dispensers: (item, first ordinal, placement count) in the boss slot's
/// region (slot 0).
const DISPENSERS_1096: [(u16, usize, usize); 2] = [(163, 0, 6), (161, 6, 7)];

/// SPEC-0041 1096 Item dispensers, one step (once the boss slot has arrived): a dispenser with
/// nothing placed puts its item at a
/// placement other than the last one used when the hero holds none of it, or 30 s (1800 ticks)
/// after the last pickup. Words 41 + k the last ordinal, 43 + k placed, 45 + k the pickup tick.
/// The spec's random-draw routine is not given: the draw is the host's raw value (`trigger_raw`)
/// modulo the other placements.
fn dispensers_1096(s: &mut GameState) -> Vec<Action> {
    let mut out = Vec::new();
    for (k, &(item, first, n)) in DISPENSERS_1096.iter().enumerate() {
        let k = k as u8;
        if s.word(1096, 43 + k) != 0 {
            continue;
        }
        let picked = s.word(1096, 45 + k);
        let held = s.items.get(&item).copied().unwrap_or(0);
        if held != 0 && !(picked >= 0 && s.hero.tick as i32 - picked >= 1800) {
            continue;
        }
        let last = s.word(1096, 41 + k);
        let raw = s.trigger_raw.wrapping_add(k as u32 * 7919);
        let j = if (0..n as i32).contains(&(last - first as i32)) {
            let r = (raw % (n as u32 - 1)) as usize;
            if r >= (last as usize - first) { r + 1 } else { r }
        } else {
            (raw % n as u32) as usize
        };
        let ordinal = first + j;
        s.set_word(1096, 41 + k, ordinal as i32);
        s.set_word(1096, 43 + k, 1);
        out.push(Action::ItemActivate { slot: 0, ordinal, snap: true, placed: true });
    }
    out
}

