/// SPEC-0044 893's score S: flags 731, 726, 727, 728, 729 and 730 as bits 0 to 5.
const SCORE_893: [u16; 6] = [731, 726, 727, 728, 729, 730];

fn score_893(s: &GameState) -> u32 {
    SCORE_893.iter().enumerate().filter(|&(_, &f)| s.flag(f)).map(|(i, _)| 1 << i).sum()
}

/// Adding n: below 40, S becomes min(S + n, 40) and the six flags are rewritten.
fn add_score_893(s: &mut GameState, n: u32) {
    let v = score_893(s);
    if v >= 40 {
        return;
    }
    let v = (v + n).min(40);
    for (i, &f) in SCORE_893.iter().enumerate() {
        s.set(f, v & (1 << i) != 0);
    }
}

/// SPEC-0044 893's proximity routines: 59 (the item 8 exchange), 41 and 58.
fn talk_893(routine: u8, s: &mut GameState) -> Vec<Action> {
    let talk = |lines: &[u16]| lines.iter().map(|&line| Action::Talk { line }).collect::<Vec<_>>();
    match routine {
        59 if s.flag(588) && !s.flag(589) => {
            s.take(86, 1);
            s.set(589, true);
            talk(&[5])
        }
        59 if s.flag(389) && s.has_item(8) => {
            let n = s.items.get(&8).copied().unwrap_or(0);
            add_score_893(s, n);
            s.remove_all(8);
            let v = score_893(s);
            let exchange = |s: &GameState| {
                let set = match (s.flag(394), s.flag(395)) {
                    (false, false) => Some(1),
                    (true, false) => Some(2),
                    (true, true) => Some(3),
                    (false, true) => None,
                };
                let mut v = vec![Action::LoadRegion { slot: 2, region: None }];
                v.extend(set.map(|j| Action::LoadRegion { slot: 2, region: Some(894 + j) }));
                v
            };
            let mut out;
            if v >= 40 {
                s.set(395, true);
                out = talk(&[6, 15]);
                out.extend(exchange(s));
            } else if v >= 25 {
                s.set(394, true);
                out = talk(&[7, 14]);
                out.extend(exchange(s));
            } else if v >= 15 {
                s.set(392, true);
                out = talk(&[8, 12]);
                out.push(Action::GiveItem { item: 138, count: 2 * n });
            } else if v >= 10 {
                s.set(391, true);
                out = talk(&[9, 13]);
                out.push(Action::GiveItem { item: 139, count: n });
            } else {
                s.set(390, true);
                out = talk(&[10, 11]);
                out.push(Action::GiveItem { item: 139, count: n });
            }
            out
        }
        59 if s.flag(394) || s.flag(395) => cycle_in(s, 893, 59, 1, &[16, 17, 18]),
        59 if s.flag(392) => talk(&[24]),
        59 if s.flag(389) => cycle_in(s, 893, 59, 2, &[19, 20, 21]),
        59 => {
            s.set(389, true);
            talk(&[22])
        }
        41 if !s.flag(526) => {
            s.set(526, true);
            let mut v = talk(&[1, 0]);
            v.extend([Action::FadeOut { seconds: FADE, wait: true }, Action::LoadRegion { slot: 1, region: None }, Action::FadeIn { seconds: FADE, wait: true }]);
            v
        }
        58 if s.flag(150) => cycle_in(s, 893, 58, 1, &[65, 66, 67]),
        58 => cycle_in(s, 893, 58, 2, &[62, 63, 64]),
        _ => Vec::new(),
    }
}

/// SPEC-0045 777's library records: the book flag, the record's objects and its extra object.
const LIBRARY_777: [(u16, &[usize], &[usize]); 5] = [(252, &[8, 9], &[7]), (253, &[10, 11, 12], &[]), (254, &[13, 14], &[]), (255, &[15], &[]), (256, &[], &[])];

/// SPEC-0045 777's proximity routines (x/y: Tor or Roberta; cases by the first set flag, each
/// three lines in turn unless noted).
fn talk_777(routine: u8, s: &mut GameState) -> Vec<Action> {
    let tor = s.hero.selected == 0;
    let f = |s: &GameState, n: u16| s.flag(n);
    // The first matching (flag, first line); a flag of 0 is the "else" case.
    let pick = |s: &GameState, rows: &[(u16, u16)]| rows.iter().position(|&(fl, _)| fl == 0 || s.flag(fl)).map(|i| (i as i32, rows[i].1));
    let three = |s: &mut GameState, case: i32, b: u16| cycle_in(s, 777, routine, case, &[b, b + 1, b + 2]);
    match routine {
        1 | 3 => {
            let (a, b, c, d, e) = if routine == 1 { (0, 3, 6, 9, (12, 13)) } else { (14, 17, 21, 24, (27, 28)) };
            if f(s, 593) {
                three(s, 1, a)
            } else if f(s, 592) {
                three(s, 2, b)
            } else if f(s, 252) {
                if tor { three(s, 3, c) } else { three(s, 4, d) }
            } else {
                vec![Action::Talk { line: if tor { e.0 } else { e.1 } }]
            }
        }
        2 => match pick(s, &[(593, 29), (592, 32), (590, 35), (86, 38), (76, 41), (258, 44), (256, 0), (252, 47), (0, 0)]) {
            Some((6, _)) => if tor { three(s, 6, 51) } else { three(s, 16, 48) },
            Some((7, _)) => vec![Action::Talk { line: 47 }],
            Some((8, _)) => if tor { three(s, 8, 57) } else { three(s, 18, 54) },
            Some((i, b)) => three(s, i, b),
            None => Vec::new(),
        },
        4 => match pick(s, &[(319, 61), (305, 64), (304, 67), (303, 70), (302, 73), (284, 76), (274, 79), (267, 82), (279, 85), (301, 88), (76, 91), (258, 94), (256, 99), (0, 102)]) {
            Some((11, _)) => cycle_in(s, 777, 4, 11, &[94, 95, 96, 97, 98]),
            Some((i, b)) => three(s, i, b),
            None => Vec::new(),
        },
        5 => match pick(s, &[(593, 106), (590, 109), (86, 112), (76, 115), (258, 118), (0, 121)]) {
            Some((5, _)) if !tor => three(s, 15, 124),
            Some((i, b)) => three(s, i, b),
            None => Vec::new(),
        },
        6..=8 => {
            let start = [127, 145, 199][routine as usize - 6];
            let i = [593, 256, 255, 254, 253].iter().position(|&fl| s.flag(fl)).unwrap_or(5);
            three(s, i as i32, start + 3 * i as u16)
        }
        9 => match pick(s, &[(593, 232), (86, 217), (76, 220), (258, 223), (0, 226)]) {
            Some((4, _)) if !tor => three(s, 14, 229),
            Some((i, b)) => three(s, i, b),
            None => Vec::new(),
        },
        _ => Vec::new(),
    }
}

