/// SPEC-0039 1246 handler 2, by level state 8, flag 273 and the fight cascade (level states 7 down
/// to 2). Each run that does more than test keeps word 1 set until it ends.
fn arena_1246(s: &mut GameState) -> Vec<Action> {
    let p = 1246;
    let mut v = Vec::new();
    let off = |v: &mut Vec<Action>| v.extend((16..=24).map(|entity| Action::DeactivateEntity { entity }));
    if s.level(8) {
        off(&mut v);
        s.set(273, true);
        v.push(Action::Sleep { ticks: 60 });
    } else if s.flag(273) {
        // The death scene and reward, in the order of SPEC-0039 1246 branch 2: the King's death
        // loop (27) for 1.3 s, the fade out, movie 42 the first time, level state 8, and only then
        // the King and entities 17 to 24 removed; swap mode 2, the hero outside the arena, item
        // 14 and line 1. The boss-fight tweak (encounter 14, stage 1) is not reproduced.
        v.extend([Action::EntityAnim { entity: 16, anim: 27, looped: true, wait: false }, wait(1.3), Action::FadeOut { seconds: 1.0, wait: true }]);
        if !s.movies.contains(&42) {
            v.push(Action::PlayFmv { movie: 42 });
        }
        v.push(Action::LevelState { flag: 8, on: true });
        off(&mut v);
        v.extend([
            Action::SwapMode { mode: 2 },
            Action::DeactivateObj { obj: 1 },
            Action::DeactivateObj { obj: 3 },
            Action::DeactivateObj { obj: 0 },
            Action::InitObjOn { obj: 2, end: false },
            Action::MoveHero { locator: 9 },
            Action::ReturnCamera { preset: -1, release: true },
            Action::FadeIn { seconds: 1.0, wait: false },
            Action::Sleep { ticks: 30 },
            Action::GiveItem { item: 14, count: 1 },
            Action::Message { line: 1 },
        ]);
    } else if s.level(7) || (s.level(5) && !s.level(6)) || (s.level(3) && !s.level(4) && !s.level(5) && !s.level(6)) {
        return Vec::new();
    } else if s.level(6) {
        s.set_level(7, true);
        v.extend([
            Action::FadeOut { seconds: FADE, wait: true },
            Action::LetterBox { on: true, seconds: 1.0, wait: false },
            Action::MoveHero { locator: 6 },
            Action::MoveEntity { entity: 16, locator: 7, face: true },
            Action::FadeIn { seconds: FADE, wait: true },
            Action::PlayCamera { track: 6, wait: false, end: 1, speed: 1.0 },
            wait(0.8),
            Action::EntityAnim { entity: 16, anim: 17, looped: false, wait: true },
            wait(0.8),
            Action::ReleaseEntity { entity: 16 },
            Action::ReturnCamera { preset: -1, release: true },
            Action::LetterBox { on: false, seconds: 1.0, wait: false },
        ]);
    } else if s.level(4) {
        s.set_level(5, true);
        v.extend([
            Action::FadeOut { seconds: FADE, wait: true },
            Action::LetterBox { on: true, seconds: 1.0, wait: false },
            Action::MoveHero { locator: 6 },
            Action::MoveEntity { entity: 16, locator: 7, face: true },
            Action::FadeIn { seconds: FADE, wait: true },
            Action::PlayCamera { track: 5, wait: false, end: 1, speed: 1.0 },
            wait(0.8),
            Action::EntityAnim { entity: 16, anim: 16, looped: false, wait: true },
            wait(0.5),
            Action::Message { line: 0 },
            Action::LetterBox { on: false, seconds: 1.0, wait: false },
            Action::ReleaseEntity { entity: 16 },
            Action::ReturnCamera { preset: -1, release: true },
        ]);
    } else if s.level(2) {
        // The intro: the gates (objects 1, 0 on, 5 off, 4 on), entity 21 off during it, camera
        // 4, the King's animation 18, entity 21 back, then SetMaxActiveAI(12) (SPEC-0019 step 6).
        s.set_level(3, true);
        v.extend([
            Action::InitObjOn { obj: 1, end: false },
            Action::InitObjOn { obj: 0, end: false },
            Action::DeactivateObj { obj: 5 },
            Action::InitObjOn { obj: 4, end: false },
            Action::DeactivateEntity { entity: 21 },
            Action::PlayCamera { track: 4, wait: false, end: 1, speed: 1.0 },
            Action::LetterBox { on: true, seconds: 1.0, wait: false },
            Action::MoveEntity { entity: 16, locator: 7, face: true },
            Action::FadeIn { seconds: FADE, wait: true },
            Action::Sleep { ticks: 30 },
            Action::WalkHero { locator: 8, wait: true, orient: false },
            Action::EntityAnim { entity: 16, anim: 18, looped: false, wait: true },
            wait(0.5),
            Action::FadeOut { seconds: FADE, wait: true },
            Action::ReturnCamera { preset: -1, release: true },
            Action::LetterBox { on: false, seconds: 1.0, wait: false },
            Action::ActivateEntity { entity: 21 },
            Action::FadeIn { seconds: FADE, wait: true },
            Action::MaxActiveAi { cap: 12 },
            Action::ReleaseEntity { entity: 16 },
        ]);
    } else {
        if s.movies.contains(&41) {
            s.set_level(2, true);
        }
        return Vec::new();
    }
    s.set_word(p, 1, 1);
    v.push(Action::Bits { word: 1, set: 0, clear: 1 });
    v
}

/// A rotation with a head line shown once and then the cycle ("a; then b, c"), with a branch
/// marker (words 10 + 2r and 11 + 2r of the pack).
fn head_then(s: &mut GameState, pack: u32, routine: u8, case: i32, head: u16, lines: &[u16]) -> Vec<Action> {
    let (cw, pw) = (10 + 2 * routine, 11 + 2 * routine);
    let mut pos = s.word(pack, pw);
    if s.word(pack, cw) != case + 1 {
        s.set_word(pack, cw, case + 1);
        pos = 0;
    }
    s.set_word(pack, pw, pos + 1);
    let line = if pos == 0 { head } else { lines[(pos as usize - 1) % lines.len()] };
    vec![Action::Talk { line }]
}

/// SPEC-0044 1327's proximity routines: 43 (the trainer, a branch marker), 1 to 5 (shared
/// counters, bases 0, 18, 36, 27, 9) and 44.
fn talk_1327(routine: u8, s: &mut GameState) -> Vec<Action> {
    let f = |s: &GameState, n: u16| s.flag(n);
    match routine {
        43 if f(s, 235) => cycle_in(s, 1327, 43, 1, &[48, 49, 50]),
        43 if f(s, 234) => vec![Action::Talk { line: 51 }],
        43 if f(s, 233) => head_then(s, 1327, 43, 3, 52, &[53, 54]),
        43 if f(s, 232) => head_then(s, 1327, 43, 4, 55, &[56, 57]),
        43 if f(s, 231) => head_then(s, 1327, 43, 5, 58, &[59, 60]),
        43 if f(s, 230) => head_then(s, 1327, 43, 6, 61, &[62, 63]),
        43 if f(s, 229) => cycle_in(s, 1327, 43, 7, &[64, 65]),
        43 if !f(s, 224) => {
            s.set(224, true);
            vec![Action::Talk { line: 74 }]
        }
        43 => {
            let line = match (f(s, 225), f(s, 226), f(s, 227)) {
                (true, true, true) => {
                    s.remove_all(10);
                    s.remove_all(11);
                    s.set(228, true);
                    s.set(229, true);
                    return vec![Action::Equip { on: true }, Action::Talk { line: 66 }];
                }
                (true, true, false) => 69,
                (true, false, true) => 68,
                (true, false, false) => 72,
                (false, true, true) => 67,
                (false, true, false) => 71,
                (false, false, true) => 70,
                (false, false, false) => 73,
            };
            vec![Action::Talk { line }]
        }
        1..=5 => {
            let b = [0, 18, 36, 27, 9][routine as usize - 1];
            let k = if f(s, 235) { 0 } else if f(s, 228) { 3 } else { 6 };
            cycle_shared(s, 1327, routine, &[b + k, b + k + 1, b + k + 2])
        }
        44 => head_then(s, 1327, 44, 1, 45, &[46, 47]),
        _ => Vec::new(),
    }
}

/// SPEC-0044 1327's target-practice thread (228 set, 234 clear; the step is the highest set of
/// 229 to 233; the trainer's talk after each step). Words: 40 the target set loaded, 41 busy,
/// 42 the step a wait belongs to, 43 the hold count, 44 the press count, 45 its 30-tick clock.
/// In steps 231 and 233 Roberta's hit points are refilled every tick (233: until AI 0 is dead).
fn practice_1327(s: &mut GameState) -> Vec<Action> {
    let p = 1327;
    if !s.flag(228) || s.flag(234) || s.word(p, 41) != 0 {
        return Vec::new();
    }
    let step = (229..=233).rev().find(|&f| s.flag(f));
    let mut out = Vec::new();
    if step.is_some() && s.word(p, 40) == 0 {
        s.set_word(p, 40, 1);
        out.extend([Action::LoadRegion { slot: 2, region: None }, Action::LoadRegion { slot: 2, region: Some(1328) }]);
    }
    let busy = |v: &mut Vec<Action>| v.push(Action::Bits { word: 41, set: 0, clear: 1 });
    let talk = |s: &mut GameState| talk_1327(43, s);
    match step {
        Some(229) if s.hero.fire => {
            s.set(230, true);
            s.set_word(p, 41, 1);
            out.push(wait(1.0));
            out.extend(talk(s));
            busy(&mut out);
        }
        Some(230) if s.word(p, 42) != 230 => {
            s.set_word(p, 42, 230);
            s.set_word(p, 41, 1);
            out.extend([
                Action::LoadRegion { slot: 2, region: None },
                Action::LoadRegion { slot: 2, region: Some(1328) },
                Action::PlayCamera { track: 0, wait: false, end: 1, speed: 1.0 },
                wait(2.5),
                Action::ReturnCamera { preset: -1, release: true },
            ]);
            busy(&mut out);
        }
        Some(230) if s.hit_now.contains(&0) => {
            s.set(231, true);
            out.push(Action::HitPointsPercent { entity: 0, percent: 100.0 });
            out.extend(talk(s));
        }
        Some(231) => {
            if s.word(p, 42) != 231 {
                s.set_word(p, 42, 231);
                out.push(Action::ActivateEntity { entity: 0 });
            }
            out.push(Action::RefillHealth);
            let held = if s.hero.fire_held { s.word(p, 43) + 1 } else { 0 };
            s.set_word(p, 43, held);
            if held >= 31 {
                s.set(232, true);
                s.set_word(p, 41, 1);
                out.extend([wait(1.5), Action::HitPointsPercent { entity: 0, percent: 100.0 }]);
                out.extend(talk(s));
                busy(&mut out);
            }
        }
        Some(232) => {
            let mut n = s.word(p, 44) + s.hero.fire as i32;
            let clock = s.word(p, 45) + 1;
            if clock >= 30 {
                n = (n - 1).max(0);
                s.set_word(p, 45, 0);
            } else {
                s.set_word(p, 45, clock);
            }
            s.set_word(p, 44, n);
            if n >= 3 {
                s.set(233, true);
                s.set_word(p, 41, 1);
                out.extend([wait(1.0), Action::HitPointsPercent { entity: 0, percent: 100.0 }]);
                out.extend(talk(s));
                out.push(Action::GiveItem { item: 160, count: 100 });
                busy(&mut out);
            }
        }
        Some(233) => {
            if s.word(p, 42) != 233 {
                s.set_word(p, 42, 233);
                out.push(Action::ActivateEntity { entity: 0 });
            }
            if !s.ai_dead.contains(&0) {
                out.push(Action::RefillHealth);
            }
            if s.ai_dead.contains(&0) {
                s.set(234, true);
                s.blackboard.insert((2, 151), 10);
                out.extend([
                    Action::Message { line: 75 },
                    Action::LoadRegion { slot: 3, region: Some(1334) },
                    Action::WaitLoads,
                    wait(0.5),
                    Action::PlayCamera { track: 5, wait: false, end: 1, speed: 1.0 },
                    Action::Message { line: 77 },
                    wait(0.3),
                    Action::ReturnCamera { preset: -1, release: true },
                    Action::LoadRegion { slot: 3, region: None },
                ]);
                out.extend(talk(s));
                s.set(235, true);
                // Movie 19; its return world eW 151 (pack 1300) is loaded at once.
                out.extend([Action::PlayFmv { movie: 19 }, Action::ReplaceExterior { slot: 151, plane: -1 }]);
            }
        }
        _ => {}
    }
    out
}

/// A routine's shared-counter cycling (no branch marker; word 11 + 2r of the pack).
fn cycle_shared(s: &mut GameState, pack: u32, routine: u8, lines: &[u16]) -> Vec<Action> {
    let w = 11 + 2 * routine;
    let c = s.word(pack, w);
    s.set_word(pack, w, c + 1);
    vec![Action::Talk { line: lines[c as usize % lines.len()] }]
}

