    #[test]
    fn module_1393_rooms() {
        let mut s = GameState::default();
        let init = on_init(1393, &mut s);
        assert_eq!(init.iter().filter(|a| matches!(a, Action::InitObjOn { .. })).count(), 35);
        assert_eq!(init.iter().filter(|a| matches!(a, Action::RegisterTrigger { .. })).count(), 23);
        assert_eq!(init.iter().filter(|a| matches!(a, Action::DisableInvisibility { .. })).count(), 8);
        let fire = |index, state| TriggerCall { index, state, object: true, square: false, block: -1 };
        // The opening runs once, before the area is active.
        let a = on_trigger(1393, 0, fire(0, 1), &mut s).actions;
        assert!(a.contains(&Action::MoveHero { locator: 4 }) && a.contains(&Action::SetFlag { flag: 697, on: true }));
        assert!(on_trigger(1393, 0, fire(0, 1), &mut s).actions.is_empty());
        // Room 1's plate works on a first pass, before any entry (its entry trigger needs the
        // area word, set past the room).
        let a = on_trigger(1393, 8, fire(8, 1), &mut s.clone()).actions;
        assert!(a.contains(&Action::InitObjOn { obj: 32, end: false }));
        // An entry needs the area word; then the plate opens the closed door once.
        assert!(on_trigger(1393, 1, fire(1, 1), &mut s).actions.is_empty());
        on_trigger(1393, 12, fire(12, 1), &mut s);
        let a = on_trigger(1393, 1, fire(1, 1), &mut s).actions;
        assert!(!a.contains(&Action::PlaySound { cue: 7, locator: None }), "the door starts closed");
        assert!(a.contains(&Action::MoveEntity { entity: 0, locator: 13, face: true }));
        let a = on_trigger(1393, 2, fire(2, 1), &mut s).actions;
        assert!(a.contains(&Action::InitObjOn { obj: 28, end: false }) && a.contains(&Action::DeactivateObj { obj: 29 }));
        assert!(on_trigger(1393, 2, fire(2, 1), &mut s).actions.is_empty(), "latched");
        // A guard in agro: the thread raises the alarm within 10 ticks, once.
        s.aggressive.insert(0);
        let mut alarm = Vec::new();
        for _ in 0..20 {
            alarm.extend(on_update(1393, &mut s, false));
        }
        assert_eq!(alarm.iter().filter(|a| **a == Action::PlaySound { cue: 5, locator: None }).count(), 1);
        assert!(alarm.contains(&Action::DeactivateObj { obj: 28 }) && alarm.contains(&Action::InitObjOn { obj: 48, end: false }));
        // The next entry closes nothing (the alarm did) and re-arms the plate.
        let a = on_trigger(1393, 1, fire(1, 1), &mut s).actions;
        assert!(!a.contains(&Action::PlaySound { cue: 7, locator: None }));
        assert!(!on_trigger(1393, 2, fire(2, 1), &mut s).actions.is_empty());
    }

    #[test]
    fn module_1324_solved_scene() {
        // R-0103: with both stage-2 marks set, the last stage-1 plate reaches the solved scene:
        // flag 239 is set before FMV 23.
        let mut s = GameState::default();
        on_init(1324, &mut s);
        let call = |index: u16, state: u8, block: i32| TriggerCall { index, state, object: false, square: false, block };
        s.set_word(1324, 8, 1);
        s.set_word(1324, 9, 1);
        on_trigger(1324, 2, call(2, 1, 0), &mut s);
        on_trigger(1324, 2, call(3, 1, 1), &mut s);
        let out = on_trigger(1324, 2, call(4, 1, 2), &mut s).actions;
        let flag = out.iter().position(|a| *a == Action::SetFlag { flag: 239, on: true }).expect("flag 239");
        let fmv = out.iter().position(|a| *a == Action::PlayFmv { movie: 23 }).expect("FMV 23");
        assert!(flag < fmv);
        assert_eq!(out.iter().filter(|a| **a == Action::Sleep { ticks: 15 }).count(), 10);
        // With one mark only, no scene.
        let mut s = GameState::default();
        on_init(1324, &mut s);
        s.set_word(1324, 8, 1);
        on_trigger(1324, 2, call(2, 1, 0), &mut s);
        on_trigger(1324, 2, call(3, 1, 1), &mut s);
        assert!(!on_trigger(1324, 2, call(4, 1, 2), &mut s).actions.contains(&Action::PlayFmv { movie: 23 }));
    }

    #[test]
    fn module_1324_plates() {
        let mut s = GameState::default();
        on_init(1324, &mut s);
        let call = |index: u16, state: u8, block: i32| TriggerCall { index, state, object: false, square: false, block };
        // The spec's vector: plate 0 entered by block 2 moves block 4 to locator 1, plays camera
        // 0 and sends the hero to locator 9, setting mark B.
        let out = on_trigger(1324, 1, call(0, 1, 2), &mut s).actions;
        assert!(out.contains(&Action::MoveBlock { block: 4, locator: 1 }));
        assert!(out.contains(&Action::PlayCamera { track: 0, wait: true, end: 1, speed: 1.0 }));
        assert!(out.contains(&Action::MoveHero { locator: 9 }));
        assert_eq!(s.word(1324, 9), 1);
        // A hero fire does nothing.
        assert!(on_trigger(1324, 1, call(1, 1, -1), &mut s).actions.is_empty());
        // Plate 2 entered by a block with plates 3 and 4 free: object 16, hero to locator 3,
        // object 26 and beam object 13 (4 s).
        let out = on_trigger(1324, 2, call(2, 1, 0), &mut s).actions;
        for a in [Action::InitObjOn { obj: 16, end: false }, Action::MoveHero { locator: 3 }, Action::InitObjOn { obj: 26, end: false }, Action::LoopAnim { obj: 13, speed: 1.0 }] {
            assert!(out.contains(&a), "{a:?}");
        }
        assert_eq!((s.word(1324, 1), s.word(1324, 6)), (14, 240));
        // Plates 3 and 4: with mark B only, the third press runs plate 0's handler again; mark A
        // then completes both marks, which reaches no FMV scene and sets no flag (SPEC-0041, R-0095).
        on_trigger(1324, 2, call(3, 1, 1), &mut s);
        let out = on_trigger(1324, 2, call(4, 1, 2), &mut s).actions;
        assert!(out.contains(&Action::InitObjOn { obj: 22, end: false }) && out.contains(&Action::MoveBlock { block: 4, locator: 1 }));
        assert!(!s.flag(239));
        let out = on_trigger(1324, 1, call(1, 1, 0), &mut s).actions;
        assert!(!out.contains(&Action::SetFlag { flag: 239, on: true }) && out.ends_with(&[Action::FadeIn { seconds: 0.5, wait: false }, Action::ReturnCamera { preset: -1, release: true }]));
        // Leaving plate 1 clears mark A; mark B left gives beam 11.
        on_trigger(1324, 1, call(1, 3, 0), &mut s);
        assert_eq!(s.word(1324, 8), 0);
    }

    #[test]
    fn module_1324_beam_rhythm() {
        // The spec's vector: P = 4.0 s, the last beat at 0, the clock at 4.01 s: a beat, object 0
        // at 1/30 s, objects 1 to 7 at 0.1 to 0.5 s over this tick and the next four.
        let mut s = GameState::default();
        s.set(239, true);
        on_init(1324, &mut s);
        s.set_word(1324, 6, 240);
        s.hero.tick = 241;
        let out = on_update(1324, &mut s, false);
        assert!(out.contains(&Action::SetObjTime { obj: 0, seconds: 1.0 / 30.0 }) && out.contains(&Action::SetObjTime { obj: 7, seconds: 0.1 }));
        for k in 2..=5 {
            s.hero.tick += 1;
            assert!(on_update(1324, &mut s, false).contains(&Action::SetObjTime { obj: 1, seconds: (3 * k) as f32 / 30.0 }));
        }
        s.hero.tick += 1;
        assert!(on_update(1324, &mut s, false).is_empty());
        // The next beat on the first tick more than 240 ticks after the last.
        s.hero.tick = 481;
        assert!(on_update(1324, &mut s, false).is_empty());
        s.hero.tick = 482;
        assert!(on_update(1324, &mut s, false).contains(&Action::SetObjTime { obj: 0, seconds: 2.0 / 30.0 }));
        // Unsolved: line 0 once; the door posts 70 for eW 155.
        let mut s = GameState::default();
        on_init(1324, &mut s);
        assert_eq!(on_update(1324, &mut s, false), vec![Action::Message { line: 0 }]);
        assert!(on_update(1324, &mut s, false).is_empty());
        assert_eq!(on_teleport(1324, 0, &mut s), vec![Action::ReplaceExterior { slot: 155, plane: -1 }]);
    }

    #[test]
    fn module_1246_arena() {
        let mut s = GameState::default();
        on_init(1246, &mut s);
        let fire = TriggerCall { index: 0, state: 2, object: true, square: false, block: -1 };
        // Before movie 41 nothing happens; the entrance marks it played.
        assert!(on_trigger(1246, 2, fire, &mut s).actions.is_empty() && !s.level(2));
        on_trigger(1246, 1, TriggerCall { index: 1, state: 1, object: true, square: false, block: -1 }, &mut s);
        // Vector 1: one fire sets level state 2 and nothing else; the next runs the intro (3).
        assert!(on_trigger(1246, 2, fire, &mut s).actions.is_empty() && s.level(2));
        assert!(on_trigger(1246, 2, fire, &mut s).actions.contains(&Action::PlayCamera { track: 4, wait: false, end: 1, speed: 1.0 }));
        assert!(s.level(3) && on_trigger(1246, 2, fire, &mut s).actions.is_empty());
        s.set_word(1246, 1, 0);
        assert!(on_trigger(1246, 2, fire, &mut s).actions.is_empty());
        // Vector 2: level states 3 and 4: the camera-5 cutscene and level state 5.
        s.set_level(4, true);
        assert!(on_trigger(1246, 2, fire, &mut s).actions.contains(&Action::Message { line: 0 }) && s.level(5));
        // Vector 3: 273 set, 8 clear: item 14 once, swap mode 2, level state 8, locator 9.
        s.set_word(1246, 1, 0);
        s.set(273, true);
        // The order: the death loop, the fade, movie 42, level state 8, then the King removed.
        let r = on_trigger(1246, 2, fire, &mut s).actions;
        assert!(r.contains(&Action::GiveItem { item: 14, count: 1 }) && r.contains(&Action::SwapMode { mode: 2 }) && r.contains(&Action::MoveHero { locator: 9 }));
        let at = |a: &Action| r.iter().position(|x| x == a).unwrap();
        assert!(at(&Action::FadeOut { seconds: 1.0, wait: true }) < at(&Action::PlayFmv { movie: 42 }));
        assert!(at(&Action::PlayFmv { movie: 42 }) < at(&Action::LevelState { flag: 8, on: true }));
        assert!(at(&Action::LevelState { flag: 8, on: true }) < at(&Action::DeactivateEntity { entity: 16 }));
        s.set_level(8, true);
        // Vector 4: 273 and 8 set: entities 16 to 24 off, no item.
        s.set_word(1246, 1, 0);
        let r = on_trigger(1246, 2, fire, &mut s).actions;
        assert!(r.contains(&Action::DeactivateEntity { entity: 24 }) && !r.contains(&Action::GiveItem { item: 14, count: 1 }));
    }

    #[test]
    fn module_1327_lines_and_practice() {
        // Vector 1: entity 43 with 229 to 235 and 224 clear: line 74 and 224; then with 225 and
        // 227 set: line 68.
        let mut s = GameState::default();
        assert_eq!(on_talk(1327, 43, &mut s), vec![Action::Talk { line: 74 }]);
        assert!(s.flag(224));
        s.give(11, 1);
        s.give(62, 1);
        on_update(1327, &mut s, false);
        assert_eq!(on_talk(1327, 43, &mut s), vec![Action::Talk { line: 68 }]);
        // Vector 2: entity 1 with 228: 3, 4; then with 235: 2, 0, 1.
        let mut s = GameState::default();
        s.set(228, true);
        let mut lines = vec![on_talk(1327, 1, &mut s), on_talk(1327, 1, &mut s)];
        s.set(235, true);
        lines.extend((0..3).map(|_| on_talk(1327, 1, &mut s)));
        assert_eq!(lines, [3, 4, 2, 0, 1].map(|line| vec![Action::Talk { line }]).to_vec());
        // Vector 3: entity 44: 45, 46, 47, 46, 47.
        let got: Vec<_> = (0..5).map(|_| on_talk(1327, 44, &mut s)).collect();
        assert_eq!(got, [45, 46, 47, 46, 47].map(|line| vec![Action::Talk { line }]).to_vec());
        // The practice: all three items start it (228, 229); a press moves to 230.
        let mut s = GameState::default();
        s.set(224, true);
        for i in [10, 11, 62] {
            s.give(i, 1);
        }
        on_update(1327, &mut s, false);
        assert!(on_talk(1327, 43, &mut s).contains(&Action::Talk { line: 66 }) && s.flag(229));
        assert!(on_update(1327, &mut s, false).contains(&Action::LoadRegion { slot: 2, region: Some(1328) }));
        assert!(s.undamageable_now.contains(&0));
        s.hero.fire = true;
        on_update(1327, &mut s, false);
        assert!(s.flag(230));
        s.hero.fire = false;
        s.set_word(1327, 41, 0);
        on_update(1327, &mut s, false);
        s.set_word(1327, 41, 0);
        // A hit on the target (it takes no damage) moves to 231; 31 ticks held to 232.
        s.hit_now.insert(0);
        on_update(1327, &mut s, false);
        assert!(s.flag(231));
        s.hit_now.clear();
        s.hero.fire_held = true;
        for _ in 0..31 {
            on_update(1327, &mut s, false);
        }
        assert!(s.flag(232));
        // Three quick presses to 233 (item 160 x100); the target's death ends it (235).
        s.set_word(1327, 41, 0);
        s.hero.fire_held = false;
        for _ in 0..3 {
            s.hero.fire = true;
            on_update(1327, &mut s, false);
        }
        assert!(s.flag(233));
        s.set_word(1327, 41, 0);
        s.hero.fire = false;
        s.ai_dead.insert(0);
        let end = on_update(1327, &mut s, false);
        assert!(end.contains(&Action::ReplaceExterior { slot: 151, plane: -1 }) && end.contains(&Action::Talk { line: 51 }));
        assert!(s.flag(234) && s.flag(235));
    }

    #[test]
    fn module_1300_lines_and_doors() {
        let mut s = GameState::default();
        let v = on_init(1300, &mut s);
        assert!(s.flag(91) && s.flag(221) && v.contains(&Action::SwapMode { mode: 1 }));
        assert!(v.contains(&Action::LoadRegion { slot: 4, region: Some(1311) }));
        // Entity 18: 399 and item 61 with line 109; then 106 to 108 until item 62 is held.
        let r = proximity_routine(1300, 18).unwrap();
        assert_eq!(on_talk(1300, r, &mut s), vec![Action::GiveItem { item: 61, count: 1 }, Action::Talk { line: 109 }]);
        assert_eq!(on_talk(1300, r, &mut s), vec![Action::Talk { line: 106 }]);
        // Trigger 0 exchanges item 61 for 62; the next talk to entity 18 plays the reward.
        s.give(61, 1);
        let enter = |i| TriggerCall { index: i, state: 1, object: true, square: false, block: -1 };
        assert!(on_trigger(1300, 3, enter(0), &mut s).actions.contains(&Action::GiveItem { item: 62, count: 1 }));
        s.give(62, 1);
        assert!(on_talk(1300, r, &mut s).contains(&Action::Talk { line: 105 }) && s.flag(400));
        // Entity 64 (routine 21): 0, 1, 2, 0. Entity 7 with 94 as Roberta: 121.
        let r = proximity_routine(1300, 64).unwrap();
        let got: Vec<_> = (0..4).map(|_| on_talk(1300, r, &mut s)).collect();
        assert_eq!(got, [0, 1, 2, 0].map(|line| vec![Action::Talk { line }]).to_vec());
        s.set(94, true);
        s.hero.selected = 1;
        assert_eq!(on_talk(1300, 1, &mut s), vec![Action::Talk { line: 121 }]);
        // Shared counter (entity 21): 74, then 78 after 235 is cleared.
        let mut s = GameState::default();
        s.set(235, true);
        assert_eq!(on_talk(1300, 8, &mut s), vec![Action::Talk { line: 74 }]);
        s.set(235, false);
        assert_eq!(on_talk(1300, 8, &mut s), vec![Action::Talk { line: 78 }]);
        // Doors: 0 enters eW 192; 2 needs 222.
        assert_eq!(on_teleport(1300, 0, &mut s), vec![Action::EnterInterior { slot: 192 }]);
        assert_eq!(on_teleport(1300, 2, &mut s), vec![Action::Message { line: 176 }]);
        // The return with 80 sets 366.
        s.blackboard.insert((2, 151), 80);
        assert!(on_activate(1300, &mut s).contains(&Action::MoveHero { locator: 2 }) && s.flag(366));
    }

