    #[test]
    fn module_1398_stage4_passes_and_stage5() {
        // Stage 4 armed: six passes by non-hero firers end it (723, region 1401); a hero fire
        // or a pass in progress starts none.
        let mut s = GameState::default();
        for f in [720, 721, 722] {
            s.set(f, true);
        }
        on_init(1398, &mut s);
        s.set_word(1398, 30, 1);
        let call = |object| TriggerCall { index: 34, state: 1, object, square: false, block: -1 };
        assert!(on_trigger(1398, 1, call(true), &mut s).actions.is_empty());
        for (k, e) in (16..=21).enumerate() {
            s.trigger_firer = Some(e);
            let a = on_trigger(1398, 1, call(false), &mut s).actions;
            assert!(a.contains(&Action::DeactivateEntity { entity: e }));
            assert!(on_trigger(1398, 1, call(false), &mut s).actions.is_empty(), "a pass runs");
            s.set_word(1398, 35, 0);
            assert_eq!(s.flag(723), k == 5);
            if k == 5 {
                assert!(a.contains(&Action::LoadRegion { slot: 0, region: Some(1401) }));
            }
        }
        // Stage 5: entities 9 to 12 on the pen meshes 7 to 10 set 724, 356 and 106.
        s.entity_mesh = [(9, 7), (10, 8), (11, 9), (12, 3)].into_iter().collect();
        on_update(1398, &mut s, false);
        assert!(!s.flag(106));
        s.entity_mesh.insert(12, 10);
        on_update(1398, &mut s, false);
        assert!(s.flag(724) && s.flag(356) && s.flag(106));
    }

    #[test]
    fn module_1398_stages() {
        let mut s = GameState::default();
        let v = on_init(1398, &mut s);
        // The pen vector: pen 2 has inner area 9, entrance 13 and locator 63; stage 1's set 0.
        assert!(v.contains(&Action::WhinnyPen { inner: 9, entrance: 13, locator: 63 }) && v.contains(&Action::LoadRegion { slot: 0, region: Some(1399) }));
        assert!(s.flag(355));
        // Stage 1: the trap arms, a hit-point drop trips it, and it can arm again.
        s.hero.hp = 20;
        let enter = |i| TriggerCall { index: i, state: 1, object: true, square: false, block: -1 };
        assert!(!on_trigger(1398, 2, enter(38), &mut s).actions.is_empty());
        assert!(on_trigger(1398, 2, enter(38), &mut s).actions.is_empty());
        assert!(on_update(1398, &mut s, false).is_empty());
        s.hero.hp = 18;
        assert!(on_update(1398, &mut s, false).contains(&Action::PlayAnim { obj: 11, speed: 1.0, wait: true }));
        assert!(!on_trigger(1398, 2, enter(38), &mut s).actions.is_empty());
        // Routine 3 ends stage 1 (720) and loads set 3 (region 1402).
        assert!(on_trigger(1398, 3, enter(33), &mut s).actions.contains(&Action::LoadRegion { slot: 0, region: Some(1402) }));
        assert!(s.flag(720));
        // Stage 2: three dead are seen on one tick and acted on the next.
        s.ai_dead.extend([13, 14, 15]);
        assert!(on_update(1398, &mut s, false).is_empty());
        assert!(on_update(1398, &mut s, false).contains(&Action::MiamouseInit { field: 15, cage: 16 }));
        assert!(s.flag(721));
        // Stage 3: four caged.
        s.miamice_caged = 4;
        assert!(on_update(1398, &mut s, false).contains(&Action::DeactivateObj { obj: 8 }));
        assert!(s.flag(722));
        // With 720 to 722 set a reload starts at stage 5's set (argument 2, region 1401).
        let mut t = GameState::default();
        for f in [720, 721, 722] {
            t.set(f, true);
        }
        assert!(on_init(1398, &mut t).contains(&Action::LoadRegion { slot: 0, region: Some(1401) }));
    }

