    #[test]
    fn module_864_chieftain_area() {
        let mut s = GameState::default();
        assert!(on_init(864, &mut s).contains(&Action::LoadRegion { slot: 0, region: Some(866) }));
        // The instance worker: group 4 (main trigger 10) loads set 4 (the Chieftain, region 869)
        // into A and set 3 into C; again, nothing; group 3 back to set 1 and set 8.
        let member = |index| TriggerCall { index, state: 1, object: true, square: false, block: -1 };
        let w = on_trigger(864, 34, member(10), &mut s).actions;
        assert!(w.contains(&Action::LoadRegion { slot: 0, region: Some(869) }) && w.contains(&Action::LoadRegion { slot: 2, region: Some(868) }));
        assert!(on_trigger(864, 34, member(10), &mut s).actions.is_empty());
        let w = on_trigger(864, 33, member(18), &mut s).actions;
        assert!(w.contains(&Action::LoadRegion { slot: 0, region: Some(866) }) && w.contains(&Action::LoadRegion { slot: 2, region: Some(873) }));
        assert!(s.flag(287) && s.level(3));
        let inside = |i| TriggerCall { index: i, state: 1, object: true, square: false, block: -1 };
        // The plain exit needs an arrival first.
        assert!(on_trigger(864, 24, inside(24), &mut s).actions.is_empty());
        on_activate(864, &mut s);
        assert_eq!(on_trigger(864, 24, inside(24), &mut s).actions, vec![Action::ReplaceExterior { slot: 50, plane: -1 }]);
        // The fight: start, then the boss's level state 0 marks the end (293) and the end stage.
        // Level state 3 clears after camera 11 (an action of the scene, after the camera).
        on_trigger(864, 1, inside(1), &mut s);
        let start = on_update(864, &mut s, false);
        assert!(start.contains(&Action::Message { line: 6 }) && s.level(3));
        // SPEC-0014 Start positions: the placements under the fade, before the cameras.
        let at = |v: &[Action], a: Action| v.iter().position(|x| *x == a).unwrap();
        let fade = at(&start, Action::FadeColour { out: true, colour: [255, 64, 32], seconds: FADE, wait: true });
        assert!(at(&start, Action::HoldHero) < fade && start.contains(&Action::PlayStinger { id: 4, volume: 1.0 }));
        let placed = at(&start, Action::MoveEntityFree { entity: 44, locator: 46, face: true });
        let tint = [255, 64, 32];
        assert!(fade < at(&start, Action::MoveHero { locator: 45 }) && placed < at(&start, Action::FadeColour { out: false, colour: tint, seconds: FADE, wait: false }));
        assert!(start.contains(&Action::CameraShakeMode { kind: 2, duration: 3.0, strength: 1.5 }));
        assert_eq!(start.iter().filter(|a| matches!(a, Action::PlayAnim { obj: 70..=92, .. })).count(), 23);
        let cam = start.iter().position(|a| matches!(a, Action::PlayCamera { track: 11, .. })).unwrap();
        assert!(start[cam..].contains(&Action::LevelState { flag: 3, on: false }));
        s.set_level(3, false);
        s.set_word(864, 6, 0);
        s.set_level(0, true);
        on_update(864, &mut s, false);
        assert!(s.flag(293));
        // SPEC-0014 Script timeline: the hold, the moves, animations 1 then 2, then entity 44 off
        // and 668 after camera 15.
        let end = on_update(864, &mut s, false);
        let hold = at(&end, Action::LevelState { flag: 3, on: true });
        let moved = at(&end, Action::MoveEntity { entity: 44, locator: 46, face: true });
        let first = at(&end, Action::EntityAnim { entity: 44, anim: 1, looped: false, wait: true });
        let second = at(&end, Action::EntityAnim { entity: 44, anim: 2, looped: false, wait: true });
        let off = at(&end, Action::DeactivateEntity { entity: 44 });
        assert!(hold < at(&end, Action::MoveHero { locator: 47 }) && hold < moved && moved < first && first < second && second < off);
        assert!(second < at(&end, Action::SetFlag { flag: 668, on: true }));
        assert_eq!(end.iter().filter(|a| matches!(a, Action::StartEffect { slot: 18..=49, .. })).count(), 33);
        // SPEC-0044: level state 2 starts the six drops once, 20 ticks apart, and holds the thread.
        let mut t = GameState::default();
        on_init(864, &mut t);
        t.set_level(2, true);
        t.set_level(0, true);
        assert_eq!(on_update(864, &mut t, false)[0], Action::Sleep { ticks: 120 });
        let stones = on_update(864, &mut t, false);
        assert_eq!(stones.iter().filter_map(|a| if let Action::PlayAnim { obj, speed, wait: false } = a { (*speed == 3.0 && *obj % 2 == 0).then_some(*obj) } else { None }).collect::<Vec<_>>(), vec![18, 20, 22, 24, 26, 28]);
        assert!(on_update(864, &mut t, false).is_empty());
        t.set_word(864, 6, 0);
        assert!(!on_update(864, &mut t, false).iter().any(|a| matches!(a, Action::PlayAnim { .. })));
        // The story exit: flags 58 and 288 to 292 and the load of eW 50.
        assert!(on_trigger(864, 22, inside(22), &mut s).actions.contains(&Action::ReplaceExterior { slot: 50, plane: -1 }));
        assert!(s.flag(58) && s.flag(290));
        // P47: line 1, flag 289.
        assert_eq!(on_talk(864, 47, &mut s)[0], Action::Talk { line: 1 });
    }

    #[test]
    fn module_985_glade_fights() {
        // The Gnarfas branch: level state 0 (Gnarfas's event) gives the movie-12 step (213, level
        // state 1); level state 2 the fight end (214); then movie 13; then trigger 4 (A2) sets 64.
        let mut s = GameState::default();
        on_init(985, &mut s);
        on_activate(985, &mut s);
        s.set_level(0, true);
        assert!(on_update(985, &mut s, false).contains(&Action::Message { line: 14 }) && s.flag(213));
        s.set_word(985, 4, 0);
        s.set_level(2, true);
        on_update(985, &mut s, false);
        assert!(s.flag(214));
        assert!(on_update(985, &mut s, false).contains(&Action::MoveHero { locator: 26 }));
        s.set_word(985, 4, 0);
        on_trigger(985, 2, TriggerCall { index: 4, state: 1, object: true, square: false, block: -1 }, &mut s);
        assert!(on_update(985, &mut s, false).contains(&Action::ReplaceExterior { slot: 74, plane: -1 }) && s.flag(64));
        // The 281 branch: the intro sets level state 0 with its last call, after the boss's
        // release; level states 7 then the end with item 30.
        let mut s = GameState::default();
        s.set(281, true);
        on_init(985, &mut s);
        on_activate(985, &mut s);
        let intro = on_update(985, &mut s, false);
        assert!(intro.contains(&Action::Converse { entity: 0, line: 5 }) && !s.level(0));
        let release = intro.iter().position(|a| *a == Action::ReleaseEntity { entity: 0 }).unwrap();
        assert_eq!(intro[release + 1], Action::LevelState { flag: 0, on: true });
        s.set_level(0, true);
        s.set_word(985, 4, 0);
        s.set_level(7, true);
        let finale = on_update(985, &mut s, false);
        assert!(s.flag(284) && finale.last() == Some(&Action::Bits { word: 4, set: 0, clear: 1 }));
        assert!(finale.contains(&Action::LevelState { flag: 8, on: true }));
        // The scene's last call (applied by the host).
        s.set_level(8, true);
        s.set_word(985, 4, 0);
        on_trigger(985, 5, TriggerCall { index: 4, state: 1, object: true, square: false, block: -1 }, &mut s);
        on_update(985, &mut s, false);
        assert!(on_update(985, &mut s, false).contains(&Action::GiveItem { item: 30, count: 1 }) && s.flag(67));
    }

    #[test]
    fn module_1096_draik_room() {
        let mut s = GameState::default();
        on_init(1096, &mut s);
        let enter = |i| TriggerCall { index: i, state: 1, object: true, square: true, block: -1 };
        // CB2: index 2 waits for index 3; index 0 for CB1.
        assert!(on_trigger(1096, 2, enter(2), &mut s).actions.is_empty());
        on_trigger(1096, 2, enter(3), &mut s);
        assert!(on_trigger(1096, 2, enter(2), &mut s).actions.contains(&Action::PlayAnim { obj: 9, speed: 0.7, wait: true }));
        assert!(on_trigger(1096, 2, enter(0), &mut s).actions.is_empty());
        assert!(on_trigger(1096, 1, enter(13), &mut s).actions.contains(&Action::WalkHero { locator: 15, wait: true, orient: true }));
        assert!(on_trigger(1096, 2, enter(0), &mut s).actions.contains(&Action::PlayAnim { obj: 7, speed: 0.7, wait: true }));
        // CB7: the Draik's level state 0 gives 1 and 2; 12 the finale (45, 316).
        s.set_level(0, true);
        on_update(1096, &mut s, false);
        assert!(s.level(1) && s.level(2));
        s.set_level(12, true);
        assert!(on_update(1096, &mut s, false).contains(&Action::SetFlag { flag: 45, on: true }));
        // After the fight: the item 117 pickup and the camera step (317).
        s.set(45, true);
        on_pickup(1096, 117, &mut s);
        assert!(on_update(1096, &mut s, false).contains(&Action::PlayCamera { track: 7, wait: true, end: 1, speed: 1.0 }) && s.flag(317));
        // CB4: the exit to eW 126.
        assert_eq!(on_trigger(1096, 4, enter(6), &mut s).actions, vec![Action::ReplaceExterior { slot: 126, plane: -1 }]);
    }

    #[test]
    fn module_1174_escape_run() {
        let mut s = GameState::default();
        on_init(1174, &mut s);
        assert!(s.level(18) && s.level(0) && s.flag(218));
        on_activate(1174, &mut s);
        // Bit 0: the arrival step; then the level-state vector: level state 2 sets bit 3, the next
        // pass bit 5.
        assert!(on_update(1174, &mut s, false).contains(&Action::WaitLoads));
        s.set_word(1174, 2, 0);
        s.set_level(2, true);
        on_update(1174, &mut s, false);
        assert!(s.word(1174, 1) & (1 << 3) != 0);
        on_update(1174, &mut s, false);
        assert!(s.word(1174, 1) & (1 << 5) != 0);
        // Section 1 (trigger 2): the barriers 50 to 53, 42 to 49 and 22, 23 raised; inside trigger
        // 30 the hero takes 3, at most once every 1.5 s.
        on_trigger(1174, 2, TriggerCall { index: 2, state: 1, object: true, square: false, block: -1 }, &mut s);
        assert!(on_update(1174, &mut s, false).contains(&Action::StartEffect { slot: 50, camera: false }));
        let inside = TriggerCall { index: 30, state: 2, object: true, square: false, block: -1 };
        s.hero.tick = 500;
        assert_eq!(on_trigger(1174, 30, inside, &mut s).actions, vec![Action::DamageHero { amount: 3 }]);
        s.hero.tick = 550;
        assert!(on_trigger(1174, 30, inside, &mut s).actions.is_empty());
        // Trigger 1: the Act 2 start (219 to 221, act start 2, eW 151), once.
        let out = on_trigger(1174, 1, TriggerCall { index: 1, state: 1, object: false, square: false, block: -1 }, &mut s).actions;
        assert!(out.contains(&Action::ActStart { stage: 2 }) && out.contains(&Action::ReplaceExterior { slot: 151, plane: -1 }) && s.flag(221));
        assert!(on_trigger(1174, 1, TriggerCall { index: 1, state: 2, object: true, square: false, block: -1 }, &mut s).actions.is_empty());
    }

    #[test]
    fn module_1428_meter_switches_and_taunts() {
        let mut s = GameState::default();
        s.set(322, true);
        on_init(1428, &mut s);
        let at = |s: &mut GameState, t: u64| {
            s.hero.tick = t;
            on_update(1428, s, false)
        };
        // Trigger 4 (S0): the boss-room return (326, item 116).
        on_trigger(1428, 2, TriggerCall { index: 4, state: 1, object: true, square: false, block: -1 }, &mut s);
        assert!(at(&mut s, 1).contains(&Action::GiveItem { item: 116, count: 1 }) && s.flag(326));
        // The meter vector: hits at 0 to 8 s and 9.5 s: 328 at 9.5 s.
        on_trigger(1428, 3, TriggerCall { index: 2, state: 1, object: true, square: false, block: -1 }, &mut s);
        for k in 0..9u64 {
            s.shot_hits = [5].into();
            at(&mut s, 100 + 60 * k);
            s.shot_hits.clear();
        }
        assert!(!s.flag(328));
        s.shot_hits = [5].into();
        at(&mut s, 100 + 570);
        s.shot_hits.clear();
        assert!(s.flag(328));
        // The switch vector: start (first, second, third); switch 0, switch 0, switch 2 gives
        // (first, first, first) and 330 once 329 is set.
        s.set(329, true);
        assert_eq!((0..3).map(|k| s.word(1428, 40 + k)).collect::<Vec<_>>(), vec![0, 1, 2]);
        for (n, idx, routine) in [(0, 6, 7), (1, 6, 7), (2, 8, 9)] {
            s.set_word(1428, 3, 0);
            let press = TriggerCall { index: idx, state: 2, object: true, square: true, block: -1 };
            on_trigger(1428, routine, press, &mut s);
            at(&mut s, 1000 + n);
        }
        assert_eq!((0..3).map(|k| s.word(1428, 40 + k)).collect::<Vec<_>>(), vec![0, 0, 0]);
        s.set_word(1428, 3, 0);
        at(&mut s, 2000);
        assert!(s.flag(330));
        // The taunts with 330: lines 0, 1, 2, 1 (delays aside; the hero alive).
        s.hero.hp = 10;
        let mut lines = Vec::new();
        for k in 0..4 {
            s.set_word(1428, 20, 0);
            let out = at(&mut s, 3000 + k);
            lines.extend(out.into_iter().filter(|a| matches!(a, Action::Message { .. })));
        }
        assert_eq!(lines, [0, 1, 2, 1].map(|line| Action::Message { line }).to_vec());
        // Trigger 0 with 330: S5, then 331 and the act start (act 4, eW 178).
        on_trigger(1428, 5, TriggerCall { index: 0, state: 1, object: true, square: false, block: -1 }, &mut s);
        at(&mut s, 4000);
        assert!(s.flag(331));
        assert!(at(&mut s, 4001).contains(&Action::ActStart { stage: 4 }) && s.flag(333));
    }

    #[test]
    fn module_1381_hub() {
        // The timed-object vector: on from 0 to 2 s (bound to the return routine), off from 2 to
        // 6 s, on again at 6 s.
        let mut s = GameState::default();
        on_init(1381, &mut s);
        let at = |s: &mut GameState, t: u64| {
            s.hero.tick = t;
            on_update(1381, s, false)
        };
        assert!(at(&mut s, 0).contains(&Action::RegisterTrigger { index: 142, routine: 4 }));
        assert!(at(&mut s, 60).iter().all(|a| !matches!(a, Action::RegisterTrigger { index: 142, .. })));
        assert!(at(&mut s, 120).contains(&Action::RegisterTrigger { index: 142, routine: 5 }));
        assert!(at(&mut s, 360).contains(&Action::RegisterTrigger { index: 142, routine: 4 }));
        // The station 1 vector: inside area 4, target 5 struck: 709 set, object 51 removed, then
        // the return to locator 0.
        let inside = |i| TriggerCall { index: i, state: 1, object: true, square: false, block: -1 };
        on_trigger(1381, 2, inside(4), &mut s);
        s.hero.strike = true;
        let out = on_trigger(1381, 3, inside(5), &mut s).actions;
        assert!(s.flag(709) && out.contains(&Action::DeactivateObj { obj: 51 }) && out.contains(&Action::MoveHero { locator: 0 }));
        // Pad 3: the hazard on; a bound hazard trigger then hurts by 5 at most every 2 s.
        let press = TriggerCall { index: 3, state: 1, object: true, square: true, block: -1 };
        // A solved station's pad does nothing.
        assert!(on_trigger(1381, 1, press, &mut s).actions.is_empty());
        s.set(709, false);
        on_trigger(1381, 1, press, &mut s);
        assert_eq!(s.word(1381, 1), 1);
        s.hero.tick = 1000;
        assert_eq!(on_trigger(1381, 6, inside(13), &mut s).actions, vec![Action::DamageHero { amount: 5 }]);
        assert!(on_trigger(1381, 6, inside(13), &mut s).actions.is_empty());
    }

    #[test]
    fn module_1096_dispensers() {
        let mut s = GameState::default();
        on_init(1096, &mut s);
        on_activate(1096, &mut s);
        // Nothing until the boss slot has arrived.
        assert!(on_update(1096, &mut s, false).iter().all(|a| !matches!(a, Action::ItemActivate { .. })));
        s.slot_alive.insert(0, 0);
        let placed = |a: &[Action]| a.iter().filter_map(|a| if let Action::ItemActivate { ordinal, .. } = a { Some(*ordinal) } else { None }).collect::<Vec<_>>();
        // Enabled by the arrival: both items placed, 163 at 0 to 5 and 161 at 6 to 12.
        let first = placed(&on_update(1096, &mut s, false));
        assert!(first.len() == 2 && first[0] < 6 && (6..13).contains(&first[1]));
        assert!(placed(&on_update(1096, &mut s, false)).is_empty());
        // Item 163 picked up and still held: placed again after 30 s, elsewhere.
        s.hero.tick = 100;
        s.items.insert(163, 1);
        on_pickup(1096, 163, &mut s);
        s.hero.tick = 1899;
        assert!(placed(&on_update(1096, &mut s, false)).is_empty());
        s.hero.tick = 1900;
        for raw in [0, 1, 2, 3, 4, 5] {
            let mut t = s.clone();
            t.trigger_raw = raw;
            let again = placed(&on_update(1096, &mut t, false));
            assert!(again.len() == 1 && again[0] < 6 && again[0] != first[0], "{again:?}");
        }
        // Used up (none held): placed again at once.
        s.hero.tick = 200;
        s.items.insert(163, 0);
        assert_eq!(placed(&on_update(1096, &mut s, false)).len(), 1);
    }

    #[test]
    fn module_1381_blocks() {
        // Init, first visit: blocks 0 to 5 inactive; the goal and arm routines registered.
        let mut s = GameState::default();
        let init = on_init(1381, &mut s);
        assert!((0..6).all(|block| init.contains(&Action::ActivateBlock { block, on: false })));
        assert!(init.contains(&Action::RegisterTrigger { index: 21, routine: 7 }) && init.contains(&Action::RegisterTrigger { index: 2, routine: 8 }));
        let fire = |index, state, block| TriggerCall { index, state, object: true, square: false, block };
        // Station 0: after 6 pushes only the goal point is touched: nothing happens.
        assert!(on_trigger(1381, 7, fire(61, 1, 0), &mut s).actions.is_empty() && !s.flag(714));
        // Another block's arm point does not arm block 0; a hero fire does nothing.
        on_trigger(1381, 8, fire(2, 1, 0), &mut s);
        on_trigger(1381, 8, fire(62, 1, -1), &mut s);
        assert_eq!(s.word(1381, ARMED_1381), 0);
        // The 7th push: the arm point, then the goal (or the goal again on the final tick).
        on_trigger(1381, 8, fire(62, 1, 0), &mut s);
        let out = on_trigger(1381, 7, fire(61, 2, 0), &mut s).actions;
        assert!(s.flag(714) && out.contains(&Action::PlaySound { cue: 9, locator: None }) && out.contains(&Action::DeactivateObj { obj: 26 }));
        assert!(on_trigger(1381, 7, fire(61, 2, 0), &mut s).actions.is_empty());
        // The block group vector: block 2 armed and not done touching a goal point.
        s.set_word(1381, ARMED_1381 + 2, 1);
        let out = on_trigger(1381, 7, fire(29, 1, 2), &mut s).actions;
        assert!(s.flag(716) && out.contains(&Action::DeactivateObj { obj: 28 }) && out.contains(&Action::DeactivateObj { obj: 22 }));
        // Leaving the arm point clears the word.
        on_trigger(1381, 8, fire(22, 3, 2), &mut s);
        assert_eq!(s.word(1381, ARMED_1381 + 2), 0);
        // The sixth piece: object 18 played, 19 removed; the pads then close.
        for k in [1, 3, 4, 5] {
            s.set_word(1381, ARMED_1381 + k, 1);
            let out = on_trigger(1381, 7, fire(61, 1, k as i32), &mut s).actions;
            assert_eq!(out.contains(&Action::DeactivateObj { obj: 19 }), k == 5);
        }
        let press = TriggerCall { index: 65, state: 1, object: true, square: true, block: -1 };
        assert!(on_trigger(1381, 1, press, &mut s).actions.is_empty());
        // The restore: station 0 solved activates block 0; pieces move to locator k + 1.
        let mut s = GameState::default();
        s.set(708, true);
        s.set(715, true);
        let r = on_activate(1381, &mut s);
        assert!(r.contains(&Action::ActivateBlock { block: 0, on: true }) && !r.contains(&Action::DeactivateObj { obj: 50 }));
        assert!(r.contains(&Action::MoveBlock { block: 1, locator: 2 }) && s.word(1381, DONE_1381 + 1) == 1);
    }

    #[test]
    fn module_1089() {
        // SPEC-0042 1089 thread A vectors: locator 0 at rest (97.591, -13.348, -475.933).
        let l = [97.591, -13.348, -475.933];
        assert!(hazard_hit_1089(l, [97.0, -13.0, -476.0]) && !hazard_hit_1089(l, [97.0, -10.0, -476.0]));
        let l = [97.591, -45.431, -475.933];
        assert!(hazard_hit_1089(l, [97.6, -44.0, -475.9]) && !hazard_hit_1089(l, [97.6, -40.0, -475.9]));
        let mut s = GameState::default();
        let init = on_init(1089, &mut s);
        assert!(init.contains(&Action::AttachObj { obj: 29, host: 0, locator: 22 }) && init.contains(&Action::RegisterAnimTrigger { host: 0, index: 3, routine: 2 }));
        // Before the hazard word routine K does nothing; T0 runs once and ends by setting it.
        let at = |index, square| TriggerCall { index, state: 2, object: true, square, block: -1 };
        assert_eq!(on_trigger(1089, 2, at(3, false), &mut s).prompt, None);
        let t0 = on_trigger(1089, 1, at(0, false), &mut s).actions;
        assert_eq!(t0.first(), Some(&Action::PlayAnim { obj: 17, speed: -1.0, wait: false }));
        assert!(on_trigger(1089, 1, at(0, false), &mut s).actions.is_empty());
        s.set_word(1089, 1, 1);
        // The press on index 3: object 29 at 1.0, 25 to 28 at 2.0, 1 s, group 3's effects; a
        // second press does nothing.
        assert_eq!(on_trigger(1089, 2, at(3, false), &mut s).prompt, Some(4));
        let press = on_trigger(1089, 2, at(3, true), &mut s).actions;
        assert_eq!(&press[..2], &[Action::SetObjTime { obj: 29, seconds: 0.0 }, Action::PlayAnim { obj: 29, speed: 1.0, wait: false }]);
        assert!(press.contains(&Action::PlayAnim { obj: 25, speed: 2.0, wait: false }) && press.ends_with(&[Action::Sleep { ticks: 60 }, Action::GroupEffects { group: 3 }]));
        assert!(on_trigger(1089, 2, at(3, true), &mut s).actions.is_empty() && s.word(1089, 3) == 1);
        // Three presses: at 18.4 the hazard stops, at 19.9 the kill and the reset.
        for i in [0, 1] {
            on_trigger(1089, 2, at(i, true), &mut s);
        }
        let tick = |s: &mut GameState, t: f32| {
            s.obj_times.insert(0, t);
            on_update(1089, s, false)
        };
        tick(&mut s, 18.5);
        assert_eq!(s.word(1089, 1), 0);
        assert!(!tick(&mut s, 19.8).contains(&Action::KillHero));
        let out = tick(&mut s, 19.95);
        assert!(out.contains(&Action::KillHero) && out.contains(&Action::MoveHero { locator: 0 }) && s.word(1089, 2) == 0);
        assert!(out.contains(&Action::InitObjOn { obj: 0, end: false }) && !tick(&mut s, 0.0).contains(&Action::KillHero));
        // Four presses: the slow-down for 120 ticks, then the stop and no kill.
        s.set_word(1089, 1, 1);
        for i in 0..4 {
            on_trigger(1089, 2, at(i, true), &mut s);
        }
        tick(&mut s, 18.5);
        let mut n = 0;
        // The slowed object 0 stays below 19.9 (about 0.6 s more at the falling speed).
        loop {
            let out = tick(&mut s, 19.0);
            assert!(!out.contains(&Action::KillHero));
            n += 1;
            if out.contains(&Action::StopAnim { obj: 0 }) {
                break;
            }
            assert!(n < 200);
        }
        assert!((119..=121).contains(&n), "{n}");
    }

    #[test]
    fn modules_1090_989() {
        // The spec's vector: bank A step 1 at tick 0 fires objects 3, 5, 7 and 4 for ticks 0 to
        // 41; none for 42 to 83; step 2 (objects 4, 6, 3, 8) at tick 84.
        let mut s = GameState::default();
        on_init(1090, &mut s);
        let fire = |s: &mut GameState, t: u64| {
            s.hero.tick = t;
            on_update(1090, s, false)
        };
        let out = fire(&mut s, 0);
        for obj in [3, 5, 7, 4] {
            assert!(out.contains(&Action::PlayAnim { obj, speed: 1.0, wait: false }));
        }
        // Inside trigger 3 (hazard 2) while it fires: 20 damage, then not again within 1 s.
        let inside = TriggerCall { index: 3, state: 2, object: true, square: false, block: -1 };
        s.hero.tick = 10;
        assert_eq!(on_trigger(1090, 1, inside, &mut s).actions, vec![Action::DamageHero { amount: 20 }]);
        s.hero.tick = 20;
        assert!(on_trigger(1090, 1, inside, &mut s).actions.is_empty());
        for t in 1..=42 {
            fire(&mut s, t);
        }
        assert_eq!(s.word(1090, 2), 0);
        let out = fire(&mut s, 84);
        for obj in [4, 6, 3, 8] {
            assert!(out.contains(&Action::PlayAnim { obj, speed: 1.0, wait: false }));
        }
        // 989: the arrival sets level state 2; the stages run to 5; the boss's defeat (level
        // state 0) leads to the post-fight block once.
        let mut s = GameState::default();
        on_activate(989, &mut s);
        on_update(989, &mut s, false);
        on_update(989, &mut s, false);
        assert!(s.level(5) && s.level(1) && s.movies.contains(&46));
        s.set_level(0, true);
        assert!(on_update(989, &mut s, false).contains(&Action::ReplaceExterior { slot: 78, plane: -1 }));
        assert!(s.flag(298) && on_update(989, &mut s, false) == vec![Action::EffectsToObjLocators { count: 8, host: 2 }]);
    }

    #[test]
    fn module_893_exchange() {
        let mut s = GameState::default();
        on_init(893, &mut s);
        assert!(s.flag(46));
        // The first talk sets 389 (line 22); then 12 of item 8: S 12, lines 9 and 13, item 139 x12.
        assert_eq!(on_talk(893, 59, &mut s), vec![Action::Talk { line: 22 }]);
        s.give(8, 12);
        let out = on_talk(893, 59, &mut s);
        assert!(out.contains(&Action::Talk { line: 9 }) && out.contains(&Action::GiveItem { item: 139, count: 12 }));
        assert_eq!(score_893(&s), 12);
        assert!(!s.flag(731) && s.flag(727) && s.flag(728) && !s.has_item(8));
        // 30 more: S capped at 40 and 395 set; with 394 clear the exchange thread only empties
        // its slot (the spec's jump straight to 40).
        s.give(8, 30);
        let out = on_talk(893, 59, &mut s);
        assert!(out.contains(&Action::Talk { line: 15 }) && out.contains(&Action::LoadRegion { slot: 2, region: None }));
        assert!(!out.iter().any(|a| matches!(a, Action::LoadRegion { slot: 2, region: Some(_) })));
        assert_eq!(score_893(&s), 40);
        assert!(s.flag(395));
        // Then lines 16, 17, 18 in turn.
        assert_eq!(on_talk(893, 59, &mut s), vec![Action::Talk { line: 16 }]);
        // Trigger 1 with 405 set loads eW 66.
        s.set(405, true);
        let press = TriggerCall { index: 1, state: 1, object: true, square: true, block: -1 };
        assert_eq!(on_trigger(893, 1, press, &mut s).actions, vec![Action::ReplaceExterior { slot: 66, plane: -1 }]);
    }

    #[test]
    fn module_1122_waves_and_arena() {
        let mut s = GameState::default();
        assert!(on_init(1122, &mut s).contains(&Action::LoadRegion { slot: 0, region: Some(1125) }));
        let enter = |i| TriggerCall { index: i, state: 1, object: true, square: false, block: -1 };
        assert!(on_trigger(1122, 5, enter(5), &mut s).actions.contains(&Action::LoadRegion { slot: 1, region: Some(1126) }));
        assert!(on_trigger(1122, 5, enter(5), &mut s).actions.is_empty());
        // The waves: each all-dead slot loads the next (sets 4, 5), then the end sets 320.
        s.set_word(1122, 2, 1);
        s.slot_alive.insert(1, 0);
        assert!(on_update(1122, &mut s, false).contains(&Action::LoadRegion { slot: 1, region: Some(1127) }));
        s.set_word(1122, 2, 2);
        assert!(on_update(1122, &mut s, false).contains(&Action::LoadRegion { slot: 1, region: Some(1128) }));
        s.set_word(1122, 2, 3);
        assert!(on_update(1122, &mut s, false).contains(&Action::MoveHero { locator: 24 }) && s.flag(320));
        // Entity 8 with 24 set: lines 25, 26, 27.
        s.set(24, true);
        assert_eq!(on_talk(1122, 8, &mut s), vec![Action::Talk { line: 25 }]);
        // The arena (31 and 320): trigger 6, then the entry; level state 2 leads to the end.
        let mut s = GameState::default();
        s.set(31, true);
        s.set(320, true);
        on_init(1122, &mut s);
        on_trigger(1122, 6, enter(6), &mut s);
        assert!(on_update(1122, &mut s, false).contains(&Action::MoveHero { locator: 26 }));
        s.set_word(1122, 4, 0);
        s.set_level(2, true);
        on_update(1122, &mut s, false);
        assert!(on_update(1122, &mut s, false).contains(&Action::ReplaceExterior { slot: 151, plane: -1 }));
        assert!(s.flag(321) && s.flag(322));
    }

    #[test]
    fn entity_table_1150() {
        // Flag 9 clear: five records (1, 2, 3, 4, 0); entity 3 walks locators 1, 2 and 3.
        let mut s = GameState::default();
        let loops = entity_setup(1150, &mut s);
        assert_eq!(loops.len(), 5);
        let t = &s.entity_tables[&1150];
        assert_eq!(t.records.iter().map(|r| r.entity).collect::<Vec<_>>(), vec![1, 2, 3, 4, 0]);
        assert_eq!(t.records[2].points.iter().map(|p| p.locator).collect::<Vec<_>>(), vec![1, 2, 3]);
        // 951: entity 4 with idle 83.
        let mut u = GameState::default();
        entity_setup(951, &mut u);
        assert_eq!(u.entity_tables[&951].records.iter().map(|r| (r.entity, r.idle)).collect::<Vec<_>>(), vec![(4, 83)]);
        // 1163: six records, entity 7 last with idle 0.
        let mut u = GameState::default();
        entity_setup(1163, &mut u);
        let t = &u.entity_tables[&1163];
        assert_eq!(t.records.iter().map(|r| (r.entity, r.idle)).collect::<Vec<_>>(), vec![(15, 65), (6, 65), (8, 65), (13, 65), (14, 65), (7, 0)]);
        // Flag 9 set: no entity 4, entity 3 walks 2 and 3.
        let mut s = GameState::default();
        s.set(9, true);
        entity_setup(1150, &mut s);
        let t = &s.entity_tables[&1150];
        assert_eq!(t.records.len(), 4);
        assert_eq!(t.records[2].points.len(), 2);
    }

    #[test]
    fn navigation_pass() {
        // 906: an unassigned entry asks for the closest mesh; an answered one (id + 1) is
        // assigned each tick; 1335 assigns entity 36 mesh 4; 1122 its fixed table.
        let mut s = GameState::default();
        let v = on_update(906, &mut s, false);
        assert_eq!(v.len(), 18);
        assert_eq!(v[0], Action::QueryNavmesh { entity: 0, word: 150 });
        s.set_word(906, 150, 3);
        assert_eq!(on_update(906, &mut s, false)[0], Action::NavmeshAssign { entity: 0, mesh: 2 });
        assert!(on_update(1335, &mut s, false).contains(&Action::NavmeshAssign { entity: 36, mesh: 4 }));
        let v = on_update(1122, &mut s, false);
        assert!(v.contains(&Action::NavmeshAssign { entity: 9, mesh: 4 }) && v.contains(&Action::NavmeshAssign { entity: 18, mesh: 1 }));
        assert!(!v.iter().any(|a| matches!(a, Action::NavmeshAssign { entity: 10, .. })));
    }

    #[test]
    fn transition_maps() {
        let mut s = GameState::default();
        let reg = |index, routine| Action::RegisterTrigger { index, routine };
        // 1255: flag 274 follows 273; index 4 is registered twice (TM5, then TM5b).
        s.set(273, true);
        assert_eq!(on_init(1255, &mut s), vec![reg(4, 0), reg(3, 0), reg(4, 1), reg(5, 1), reg(0, 2), reg(1, 2)]);
        assert!(s.flag(274));
        assert_eq!(s.transition_map, None);
        // Any call for the trigger sets the map, with no state test; a later one replaces it.
        let call = TriggerCall { index: 0, state: 0, object: false, square: false, block: -1 };
        on_trigger(1255, 2, call, &mut s);
        assert_eq!(s.transition_map, Some(7));
        on_trigger(1122, 3, call, &mut s);
        assert_eq!(s.transition_map, Some(52));
        on_trigger(696, 5, call, &mut s);
        assert_eq!(s.transition_map, Some(73));
        // 685 and 1098 register their map triggers.
        assert_eq!(on_init(685, &mut s), vec![reg(0, 0), reg(1, 1)]);
        assert!(on_init(1098, &mut GameState::default()).iter().take(3).eq([reg(0, 1), reg(7, 7), reg(8, 8)].iter()));
        on_trigger(1098, 8, call, &mut s);
        assert_eq!(s.transition_map, Some(49));
    }

