    #[test]
    fn module_1174_floor_tiles() {
        let mut s = GameState::default();
        on_init(1174, &mut s);
        s.set_word(1174, 1, 3);
        on_activate(1174, &mut s);
        assert!(s.act1_map.contains(&(5, true)) && s.act1_map.contains(&(36, true)) && !s.act1_map.iter().any(|p| p.0 == 40));
        // SPEC-0044's vector: tile 36 fired at clock 10.0: object 37 off, 38 to 48 on and playing,
        // effect 92, sound 7 at locator 73.
        s.hero.tick = 600;
        let call = |index| TriggerCall { index, state: 1, object: false, square: false, block: -1 };
        let out = on_trigger(1174, 36, call(36), &mut s).actions;
        assert_eq!(out[0], Action::DeactivateObj { obj: 37 });
        assert!(out.contains(&Action::PlayAnim { obj: 48, speed: 1.0, wait: false }) && out.contains(&Action::StartEffect { slot: 92, camera: false }));
        assert!(out.contains(&Action::PlaySound { cue: 7, locator: Some(73) }));
        assert!(s.act1_map.contains(&(36, false)));
        // A second fire does nothing; the hero's body fires nothing.
        assert!(on_trigger(1174, 36, call(36), &mut s).actions.is_empty());
        assert!(on_trigger(1174, 36, TriggerCall { object: true, ..call(37) }, &mut s).actions.is_empty());
        // At 10.85+ sounds 7 and 8; after 1.4 s only piece 38 stays.
        s.hero.tick = 652;
        let v = tiles_1174(&mut s);
        assert!(v.contains(&Action::PlaySound { cue: 8, locator: Some(73) }) && v.contains(&Action::PlaySound { cue: 7, locator: Some(73) }));
        s.hero.tick = 685;
        let v = tiles_1174(&mut s);
        assert!(v.contains(&Action::DeactivateObj { obj: 39 }) && !v.contains(&Action::DeactivateObj { obj: 38 }));
        assert_eq!(s.word(1174, 100), 4);
        // Tile 43 fired at 20.0 drops tile 42 on the first pass after 21.7 and asks for bit 8.
        section_1174(&mut s, 1);
        s.hero.tick = 1200;
        on_trigger(1174, 36, call(43), &mut s);
        s.hero.tick = 1300;
        assert!(tiles_1174(&mut s).contains(&Action::CollisMask { mask: 5 }));
        assert_eq!(s.word(1174, 106), 0);
        s.hero.tick = 1303;
        assert!(tiles_1174(&mut s).contains(&Action::DeactivateObj { obj: 109 }));
        assert_eq!(s.word(1174, 106), 1);
        // A section record counts once.
        let enter = TriggerCall { index: 3, state: 1, object: true, square: false, block: -1 };
        on_trigger(1174, 2, enter, &mut s);
        assert!(s.act1_map.iter().any(|p| p.0 == 46));
        // A breakable by object 0.
        let out = on_trigger(1174, 22, call(24), &mut s).actions;
        assert!(out.contains(&Action::Break { id: 5 }) && out.contains(&Action::PlaySound { cue: 9, locator: Some(67) }));
    }

    #[test]
    fn module_1056_nests_and_knights() {
        let mut s = GameState::default();
        // Before 174, and not the listed nests: a hook with no effect, or none.
        assert_eq!(on_breakable(1056, 24, 3, &mut s), Some(Vec::new()));
        assert_eq!(on_breakable(1056, 25, 3, &mut s), None);
        assert!(on_breakable(735, 4, 1, &mut s).is_some() && on_breakable(735, 3, 1, &mut s).is_none());
        s.set(174, true);
        for (script, flag, line) in [(24, 625, 72), (27, 626, 73), (30, 627, 74), (33, 628, 75), (36, 629, 76)] {
            assert_eq!(on_breakable(1056, script, 9, &mut s), Some(vec![Action::Break { id: 9 }, Action::Message { line }]));
            assert!(s.flag(flag));
        }
        assert!(s.flag(179));
        // Prunella then sets 501, once.
        assert_eq!(on_talk(1056, proximity_routine(1056, 0).unwrap(), &mut s), vec![Action::Talk { line: 155 }]);
        assert!(s.flag(501));
        for line in [152, 153, 154, 152] {
            assert_eq!(on_talk(1056, 43, &mut s), vec![Action::Talk { line }]);
        }
        // The charm in 1098 sets 502, once 501 is on (and not before).
        let mut early = GameState::default();
        early.give(72, 1);
        on_update(1098, &mut early, false);
        assert!(!early.flag(502));
        s.give(72, 1);
        on_update(1098, &mut s, false);
        assert!(s.flag(502));
        // With 502 a knight asks; yes takes the charm and shuts the other out.
        assert_eq!(on_talk(1056, proximity_routine(1056, 41).unwrap(), &mut s), vec![Action::Prompt { line: 110, routine: 38 }]);
        assert_eq!(on_answer(1056, 38, true, &mut s), vec![Action::Talk { line: 113 }]);
        assert!(s.flag(503) && s.flag(505) && !s.has_item(72));
        assert_eq!(on_talk(1056, 39, &mut s), vec![Action::Talk { line: 79 }]);
    }

    #[test]
    fn module_722_bogshot_village() {
        let mut s = GameState::default();
        s.set(76, true);
        s.set(562, true);
        let init = on_init(722, &mut s);
        assert!(init.contains(&Action::LoadRegion { slot: 0, region: Some(726) }) && init.contains(&Action::LoadRegion { slot: 1, region: Some(727) }) && init.contains(&Action::LoadRegion { slot: 4, region: Some(723) }));
        let mut c = GameState::default();
        c.set(75, true);
        let init = on_init(722, &mut c);
        assert!(init.contains(&Action::LoadRegion { slot: 0, region: Some(725) }) && init.contains(&Action::LoadRegion { slot: 3, region: Some(730) }));
        // Doors, and the arrival from the apothecary.
        assert_eq!(on_teleport(722, 3, &mut s)[0], Action::EnterInterior { slot: 24 });
        assert_eq!(teleport_context(722, 4), Some(13));
        s.blackboard.insert((2, 20), 10);
        assert!(on_activate(722, &mut s).contains(&Action::MoveHero { locator: 110 }));
        s.blackboard.insert((2, 20), 50);
        assert!(on_activate(722, &mut s).contains(&Action::MoveHero { locator: 106 }));
        // SPEC-0044 test vector: R1 with 562 and 561 clear and 76 set: line 18 and 561; then 15, 16, 17, 15.
        let mut t = GameState::default();
        t.set(76, true);
        let r = proximity_routine(722, 10).unwrap();
        assert_eq!(on_talk(722, r, &mut t), vec![Action::Talk { line: 18 }]);
        assert!(t.flag(561));
        for line in [15, 16, 17, 15] {
            assert_eq!(on_talk(722, r, &mut t), vec![Action::Talk { line }]);
        }
        // SPEC-0044 test vector: a bet on racer 1 at odds (2, 3, 1), S = 6, with 120 Neopoints.
        for (k, v) in [(10, 2), (11, 3), (12, 1), (13, 6)] {
            s.set_word(722, k, v);
        }
        s.neopoints = 120;
        let call = TriggerCall { index: 1, state: 2, object: true, square: true, block: -1 };
        let bet = on_trigger(722, 1, call, &mut s);
        assert_eq!(bet.prompt, Some(4));
        assert_eq!(bet.actions, vec![Action::Prompt { line: 69, routine: 1 }]);
        on_answer(722, 1, true, &mut s);
        assert_eq!((s.neopoints, s.word(722, 27), s.word(722, 20)), (70, 1, 1));
        assert!(on_update(722, &mut s, false).contains(&Action::MoveHero { locator: 4 }));
        assert!(on_update(722, &mut s, false).is_empty(), "the scene holds the thread");
        // Racer 1 wins: its 16th step ends the race with line 72 and 3 of item 139.
        s.set_word(722, 21, 0);
        s.set_word(722, 23, 15);
        let mut end = Vec::new();
        for raw in 0..2000u32 {
            s.trigger_raw = raw.wrapping_mul(2_654_435_761);
            s.set_word(722, 21, 0);
            s.set_word(722, 22, 0);
            s.set_word(722, 24, 0);
            let v = on_update(722, &mut s, false);
            if v.contains(&Action::Message { line: 72 }) {
                end = v;
                break;
            }
        }
        assert!(end.contains(&Action::GiveItem { item: 139, count: 3 }));
        assert_eq!(s.word(722, 20), 0);
        // Too few Neopoints: line 75 and no race.
        s.neopoints = 49;
        assert_eq!(on_answer(722, 0, true, &mut s)[0], Action::Message { line: 75 });
        assert_eq!(s.word(722, 20), 0);
    }

