    #[test]
    fn module_1432_control_thread_b() {
        // SPEC-0054 test vector: rules passing from tick T with all markers clear place entity 7
        // at T+480, 6 at T+960 and 5 at T+1440. The filter refuses the Grunts' records only.
        assert_eq!((admits(1432, 5, &GameState::default()), admits(1432, 7, &GameState::default()), admits(1432, 0, &GameState::default())), (Some(false), Some(false), Some(true)));
        let mut s = GameState::default();
        s.set_level(11, true);
        s.hero.selected = 0;
        assert!((0..1000).all(|_| grunts_1432(&mut s).is_empty()));
        s.hero.selected = 1;
        s.entity_hp.extend([(5, 50), (6, 50), (7, 50)]);
        let mut placed = Vec::new();
        for t in 0..=2000 {
            for a in grunts_1432(&mut s) {
                if let Action::MoveEntityAir { entity, locator: 4 } = a {
                    placed.push((t, entity));
                }
            }
        }
        assert_eq!(placed, vec![(480, 7), (960, 6), (1440, 5)]);
        // A live Grunt stays; a dead one comes back after 480 ticks.
        s.entity_hp.insert(6, 0);
        let mut back = Vec::new();
        for t in 0..=480 {
            for a in grunts_1432(&mut s) {
                if let Action::MoveEntityAir { entity, .. } = a {
                    back.push((t, entity));
                }
            }
        }
        assert_eq!(back, vec![(480, 6)]);
        // Level state 12 during the wait: no move, and it stops the thread.
        let mut s = GameState::default();
        s.set_level(11, true);
        s.hero.selected = 1;
        grunts_1432(&mut s);
        s.set_level(12, true);
        assert!((0..2000).all(|_| grunts_1432(&mut s).is_empty()));
        assert_eq!(s.word(1432, 6), 0);
    }

    #[test]
    fn module_1432_final_fight() {
        // The thread's own writes (Bits, LevelState, SetFlag, the timer) as the host applies them.
        fn run(v: Vec<Action>, s: &mut GameState) -> Vec<Action> {
            for a in &v {
                match *a {
                    Action::Bits { word, set, clear } => s.set_word(1432, word, (s.word(1432, word) | set) & !clear),
                    Action::LevelState { flag, on } => s.set_level(flag, on),
                    Action::SetFlag { flag, on } => s.set(flag, on),
                    Action::ActivateTimer { start, limit, up } => s.timer.activate(start, limit, up),
                    _ => {}
                }
            }
            v
        }
        let mut s = GameState::default();
        let v = on_init(1432, &mut s);
        assert!(s.flag(364) && s.flag(358) && v.contains(&Action::RegisterTrigger { index: 1, routine: 1 }));
        on_activate(1432, &mut s);
        assert!(s.level(10));
        // Rule 6, the fight start step, once: camera 4 without waiting, and the hero moved to the
        // hall centre (locator 1).
        let start = run(on_update(1432, &mut s, false), &mut s);
        assert!(start.contains(&Action::PlayCamera { track: 4, wait: false, end: 1, speed: 1.0 }) && start.contains(&Action::MoveHero { locator: 1 }));
        assert!(on_update(1432, &mut s, false).is_empty());
        // Trigger 1 before the window: nothing. Trigger 0, then the entry: the clock at 180,
        // level 11 on and 10 off, movie 78.
        let fire = |o| TriggerCall { index: 0, state: 1, object: o, square: false, block: -1 };
        on_trigger(1432, 1, fire(true), &mut s);
        assert_eq!(s.word(1432, 1) & 1 << 4, 0);
        on_trigger(1432, 0, fire(true), &mut s);
        let v = run(on_update(1432, &mut s, false), &mut s);
        assert!(v.contains(&Action::MoveEntity { entity: 0, locator: 2, face: false }) && s.movies.contains(&78));
        assert!(s.level(11) && !s.level(10) && s.timer.value == 180.0);
        // The landed window: armed on level 16 (900 ticks), then level 13 at its end.
        s.set_level(16, true);
        on_update(1432, &mut s, false);
        assert_eq!(s.word(1432, 3), 900);
        // Trigger 1 inside the window: a shot's fire (object 0) does not pass; the hero's does.
        on_trigger(1432, 1, fire(false), &mut s);
        assert_eq!(s.word(1432, 1) & 1 << 4, 0);
        let mut t = s.clone();
        on_trigger(1432, 1, fire(true), &mut t);
        let v = run(on_update(1432, &mut t, false), &mut t);
        assert!(v.contains(&Action::ReplaceExterior { slot: 151, plane: -1 }) && t.flag(94) && t.flag(365));
        assert_eq!(t.blackboard.get(&(2, 151)), Some(&80));
        for _ in 0..900 {
            on_update(1432, &mut s, false);
        }
        assert!(!s.level(16) && s.level(13));
        // The landed-miss swap with Roberta active: the clock stops; its completion sets 15.
        s.hero.selected = 1;
        let v = on_update(1432, &mut s, false);
        assert!(v.contains(&Action::SwitchHero { hero: 0, effects: true, flash: true }) && !s.timer.running);
        s.hero.swapping = true;
        on_update(1432, &mut s, false);
        s.hero.swapping = false;
        s.hero.selected = 0;
        on_update(1432, &mut s, false);
        assert!(s.level(15) && !s.level(13) && s.timer.running);
        // The timeout: the clock at 0.0 sets flag 2, and the ending runs (movie 80).
        s.timer.value = 0.0;
        on_update(1432, &mut s, false);
        let v = run(on_update(1432, &mut s, false), &mut s);
        assert!(s.movies.contains(&80) && v.contains(&Action::DeactivateEntity { entity: 0 }));
    }

    #[test]
    fn module_956_glade() {
        // Act 1 (h 62): set 7 into slot S (region 964), the effects on, the cages registered.
        let mut s = GameState::default();
        s.set(62, true);
        let v = on_init(956, &mut s);
        assert!(v.contains(&Action::LoadRegion { slot: 0, region: Some(964) }) && v.contains(&Action::StartEffect { slot: 9, camera: false }));
        assert!(v.contains(&Action::RegisterTrigger { index: 23, routine: 21 }));
        // The spec's cage vector, first half: record 1's guard (AI 24) dead, lock 5 intact: the
        // lock made breakable and line 78, once (the full vector is in module_956_knights).
        s.ai_dead.insert(24);
        s.breakables.insert(5, 3);
        let inside = TriggerCall { index: 23, state: 2, object: true, square: false, block: -1 };
        assert_eq!(on_trigger(956, 21, inside, &mut s).actions, vec![Action::MakeBreakable { id: 5, on: true }, Action::Message { line: 78 }]);
        assert!(on_trigger(956, 21, inside, &mut s).actions.is_empty());
        // Zone trigger 4 loads region 961 while the hero is inside.
        let enter = |i| TriggerCall { index: i, state: 1, object: true, square: false, block: -1 };
        assert!(on_trigger(956, 3, enter(4), &mut s).actions.contains(&Action::LoadRegion { slot: 1, region: Some(961) }));
        // The lift: not ready until the knights are free.
        assert!(on_trigger(956, 8, enter(8), &mut s).actions.is_empty());
        for f in [208, 209, 210, 623] {
            s.set(f, true);
        }
        assert!(on_trigger(956, 8, enter(8), &mut s).actions.contains(&Action::PlayAnim { obj: 9, speed: 1.0, wait: false }));
        assert!(s.flag(211));
        // The aftermath (214 set): flags 216 and 64, set 8 into S (region 965).
        s.set(214, true);
        let out = on_update(956, &mut s, false);
        assert!(out.contains(&Action::LoadRegion { slot: 0, region: Some(965) }) && out.contains(&Action::Message { line: 72 }));
        assert!(s.flag(216) && s.flag(64) && on_update(956, &mut s, false).iter().all(|a| matches!(a, Action::QueryNavmesh { .. } | Action::NavmeshAssign { .. })));
        // The door: line 71 with 64 set and 67 clear.
        assert_eq!(on_teleport(956, 0, &mut s), vec![Action::Message { line: 71 }]);
    }

    #[test]
    fn module_956_knights() {
        // The spec's vector: record 1, guard AI 24 dead, lock 5 intact, the hero in trigger 23.
        let mut s = GameState::default();
        let init = on_init(956, &mut s);
        assert!(init.contains(&Action::MakeBreakable { id: 5, on: false }) && init.contains(&Action::RegisterTrigger { index: 23, routine: 21 }));
        let at = |square| TriggerCall { index: 23, state: 2, object: true, square, block: -1 };
        s.breakables.insert(5, 3);
        assert_eq!(on_trigger(956, 21, at(false), &mut s).prompt, Some(3));
        s.ai_dead.insert(24);
        let out = on_trigger(956, 21, at(false), &mut s).actions;
        assert_eq!(out, vec![Action::MakeBreakable { id: 5, on: true }, Action::Message { line: 78 }]);
        assert!(on_trigger(956, 21, at(false), &mut s).actions.is_empty());
        // The lock broken: context 6; Square: knight 4 to locator 59, line 77, flag 209.
        s.breakables.insert(5, 2);
        assert_eq!(on_trigger(956, 21, at(false), &mut s).prompt, Some(6));
        let out = on_trigger(956, 21, at(true), &mut s).actions;
        assert!(out.contains(&Action::MoveEntity { entity: 4, locator: 59, face: true }) && out.contains(&Action::Converse { entity: 4, line: 77 }));
        assert!(out.contains(&Action::SetFlag { flag: 209, on: true }) && !out.contains(&Action::SetFlag { flag: 211, on: true }));
        assert!(on_trigger(956, 21, at(true), &mut s).actions.is_empty());
        // The last knight freed also sets 211; with 211 set at load the locks are broken.
        let mut s = GameState::default();
        for f in [208, 209, 210] {
            s.set(f, true);
        }
        s.ai_dead.insert(26);
        s.breakables.insert(6, 2);
        let out = on_trigger(956, 21, TriggerCall { index: 24, state: 1, object: true, square: true, block: -1 }, &mut s).actions;
        assert!(out.contains(&Action::SetFlag { flag: 623, on: true }) && out.contains(&Action::SetFlag { flag: 211, on: true }));
        s.set(211, true);
        assert!(on_init(956, &mut s).contains(&Action::Break { id: 3 }));
    }

    #[test]
    fn module_777_library() {
        // The library set-up vector: 252 and 254 set, 253 and 255 clear: objects 7, 8, 9, 13 and
        // 14 at their end pose, 10 to 12 at their start, 15 not set up.
        let mut s = GameState::default();
        s.set(252, true);
        s.set(254, true);
        let v = on_init(777, &mut s);
        for obj in [7, 8, 9, 13, 14] {
            assert!(v.contains(&Action::InitObjOn { obj, end: true }), "{obj}");
        }
        for obj in [10, 11, 12] {
            assert!(v.contains(&Action::InitObjOn { obj, end: false }));
        }
        assert!(!v.iter().any(|a| matches!(a, Action::InitObjOn { obj: 15, .. })));
        // The soft-lock vector: 252 set, 253 to 256 clear; the middle book (8) sets 256 with line
        // 240; the south book then does nothing; the door shows line 235.
        let mut s = GameState::default();
        s.set(252, true);
        on_init(777, &mut s);
        let press = |i| TriggerCall { index: i, state: 1, object: true, square: true, block: -1 };
        assert!(on_trigger(777, 11, press(8), &mut s).actions.contains(&Action::Message { line: 240 }));
        assert!(s.flag(256) && on_trigger(777, 11, press(5), &mut s).actions.is_empty());
        assert_eq!(on_teleport(777, 0, &mut s)[0], Action::Message { line: 235 });
        // Books in order: 5 then 6 (object 15 shown, 14 hidden).
        let mut s = GameState::default();
        s.set(252, true);
        on_init(777, &mut s);
        assert!(on_trigger(777, 11, press(5), &mut s).actions.contains(&Action::Message { line: 237 }));
        assert!(on_trigger(777, 11, press(6), &mut s).actions.contains(&Action::InitObjOn { obj: 15, end: false }));
        // The quest state: the AI deaths end it (593, item 152).
        let mut s = GameState::default();
        s.set(592, true);
        assert!(on_init(777, &mut s).contains(&Action::LoadRegion { slot: 2, region: Some(781) }));
        s.ai_dead.extend(6..=10);
        assert!(on_update(777, &mut s, false).contains(&Action::GiveItem { item: 152, count: 1 }) && s.flag(593));
        // Routine 4 with 258: the five-line cycle.
        let mut s = GameState::default();
        s.set(258, true);
        let got: Vec<_> = (0..6).map(|_| on_talk(777, 4, &mut s)).collect();
        assert_eq!(got, [94, 95, 96, 97, 98, 94].map(|line| vec![Action::Talk { line }]).to_vec());
        // Routine 9 as Roberta (no flags): 229.
        s.hero.selected = 1;
        let mut t = GameState::default();
        t.hero.selected = 1;
        assert_eq!(on_talk(777, 9, &mut t), vec![Action::Talk { line: 229 }]);
    }

    #[test]
    fn module_1078_doors() {
        let mut s = GameState::default();
        on_init(1078, &mut s);
        assert!(s.flag(309));
        let enter = |i| TriggerCall { index: i, state: 1, object: true, square: true, block: -1 };
        // Plate 5 (record 2): both doors open with camera 8 the first time; once the firer
        // leaves Update closes them.
        let out = on_trigger(1078, 3, enter(5), &mut s).actions;
        assert!(out.contains(&Action::PlayAnim { obj: 21, speed: 1.0, wait: false }) && out.contains(&Action::PlayCamera { track: 8, wait: false, end: 1, speed: 1.0 }));
        s.set_word(1078, 42, 2);
        assert!(on_update(1078, &mut s, false).contains(&Action::InitObjOn { obj: 16, end: false }));
        // A second press shows no camera; a lever pull (28) sets 673 and keeps the doors open.
        assert!(!on_trigger(1078, 3, enter(5), &mut s).actions.contains(&Action::PlayCamera { track: 8, wait: false, end: 1, speed: 1.0 }));
        assert!(on_trigger(1078, 26, enter(28), &mut s).actions.contains(&Action::WalkHero { locator: 19, wait: true, orient: true }));
        assert!(s.flag(673));
        s.set_word(1078, 42, 2);
        assert!(on_update(1078, &mut s, false).is_empty());
        // The item check: without item 18 or 312 line 1 and 311; the short sequence first.
        assert!(on_trigger(1078, 0, enter(0), &mut s).actions.is_empty());
        on_trigger(1078, 1, enter(1), &mut s);
        assert_eq!(on_trigger(1078, 0, enter(0), &mut s).actions, vec![Action::Message { line: 1 }]);
        assert!(s.flag(311));
        s.give(18, 1);
        assert!(on_trigger(1078, 0, enter(0), &mut s).actions.contains(&Action::PlayAnim { obj: 0, speed: 1.0, wait: true }));
    }

