    #[test]
    fn module_735_boss_and_callback() {
        let mut s = GameState::default();
        assert!(on_init(735, &mut s).contains(&Action::LoadRegion { slot: 0, region: Some(738) }));
        let enter = |i| TriggerCall { index: i, state: 1, object: true, square: false, block: -1 };
        on_trigger(735, 23, enter(23), &mut s);
        assert!(s.level(8));
        // The intro sets 9 and keeps the hit points; the monitor's AI 73 death leads to the
        // victory, which clears the post-fight word.
        s.hero.hp = 20;
        s.entity_hp.insert(73, 50);
        assert!(on_update(735, &mut s, false).contains(&Action::LoadRegion { slot: 1, region: Some(740) }));
        assert!(s.level(9) && s.word(735, 3) == 20);
        s.set_word(735, 1, 0);
        // Line 3 once, 5 s after the hero is hurt while AI 73 is not.
        s.hero.hp = 18;
        s.hero.tick = 1000;
        // The platform-time thread sees level state 13 set by the intro: the later times.
        let times = on_update(735, &mut s, false);
        assert!(times.contains(&Action::SetObjTime { obj: 54, seconds: 1.0 }) && times.contains(&Action::SetObjTime { obj: 52, seconds: 1.5 }) && times.len() == 5);
        assert!(on_update(735, &mut s, false).is_empty());
        s.hero.tick = 1301;
        assert_eq!(on_update(735, &mut s, false), vec![Action::Message { line: 3 }]);
        s.ai_dead.insert(73);
        on_update(735, &mut s, false);
        assert!(s.level(11));
        assert!(on_update(735, &mut s, false).contains(&Action::Message { line: 2 }) && s.flag(263));
        // The death callback: in the post-fight window the hero goes to locator 5; after trigger
        // 2 the current hero is killed.
        let (skip, v) = on_hero_death(735, 0, &mut s).unwrap();
        assert!(skip && v.contains(&Action::MoveHero { locator: 5 }));
        s.set_word(735, 250, 0);
        on_trigger(735, 2, enter(2), &mut s);
        assert!(on_hero_death(735, 0, &mut s).unwrap().1.contains(&Action::KillHero));
    }

    #[test]
    fn shield_lesson_1056() {
        let mut s = GameState::default();
        s.set(26, true);
        s.set(188, true);
        s.set_word(1056, 11, 1);
        // A fire shield with Square held: 189, the launcher still off.
        s.hero.shield_mote = Some(160);
        s.hero.square_held = true;
        super::yard_update(&mut s, false);
        assert!(s.flag(189) && s.word(1056, 12) == 0);
        // Square released: the launcher on; it fires at once and again 181 ticks later.
        s.hero.square_held = false;
        let shots = (0..200).flat_map(|_| super::yard_update(&mut s, false)).filter(|a| matches!(a, Action::LaunchFireMote { from: 101, to: 102, .. })).count();
        assert_eq!(shots, 2);
        // A deflected shot: 190 and the launcher off.
        s.hero.deflected = true;
        super::yard_update(&mut s, false);
        assert!(s.flag(190) && s.word(1056, 12) == 0);
        // A non-fire shield before a deflection clears 189.
        let mut t = GameState::default();
        t.set(26, true);
        t.set(188, true);
        t.set(189, true);
        t.set_word(1056, 14, 2);
        t.set_word(1056, 12, 1);
        t.hero.shield_mote = Some(162);
        super::yard_update(&mut t, false);
        assert!(!t.flag(189) && t.word(1056, 12) == 0);
    }

