    #[test]
    fn hero_death_callbacks() {
        // 1371 round: the first death switches to the partner and skips the default death; the
        // second marks the round lost, which the watcher turns into the lost result.
        let mut s = GameState::default();
        s.blackboard.insert((2, 157), 20);
        on_init(1371, &mut s);
        let (flag, v) = on_hero_death(1371, 0, &mut s).unwrap();
        assert!(flag && v.contains(&Action::SwitchHero { hero: 1, effects: true, flash: true }));
        s.set_word(1371, 250, 0);
        let (_, v) = on_hero_death(1371, 1, &mut s).unwrap();
        assert!(v.contains(&Action::HeroAnim { anim: 34, wait: false }));
        assert!(on_update(1371, &mut s, false).contains(&Action::ReplaceExterior { slot: 157, plane: 0 }));
        assert!(s.flag(595) && s.blackboard.get(&(1, 157)) == Some(&-1));
        // 1394: flag 0 and the checkpoint respawn; a second death while it runs starts nothing.
        let mut s = GameState::default();
        on_init(1394, &mut s);
        let (flag, v) = on_hero_death(1394, 0, &mut s).unwrap();
        assert!(!flag && v.contains(&Action::MoveHero { locator: 0 }));
        assert!(on_hero_death(1394, 0, &mut s).unwrap().1.is_empty());
        // No callback elsewhere (and 1371 outside a round).
        assert!(on_hero_death(909, 0, &mut s).is_none() && on_hero_death(1371, 0, &mut GameState::default()).is_none());
    }

    #[test]
    fn module_1371_wave_trial() {
        let mut s = GameState::default();
        on_init(1371, &mut s);
        let enter = |i| TriggerCall { index: i, state: 1, object: true, square: false, block: -1 };
        // Gates 4 and 3 are shut before wave 6; gate 2 opens it (region 1378).
        assert!(on_trigger(1371, 2, enter(4), &mut s).actions.is_empty());
        assert!(on_trigger(1371, 2, enter(3), &mut s).actions.is_empty());
        let out = on_trigger(1371, 2, enter(2), &mut s).actions;
        assert!(out.contains(&Action::LoadRegion { slot: 0, region: Some(1378) }) && out.contains(&Action::WalkHero { locator: 23, wait: true, orient: true }));
        // The wave word set by the thread; scored only once the slot's characters are all dead.
        s.set_word(1371, 1, 6);
        s.slot_alive.insert(0, 2);
        assert!(on_update(1371, &mut s, false).is_empty());
        s.slot_alive.insert(0, 0);
        assert!(!on_update(1371, &mut s, false).is_empty());
        assert!(s.flag(342) && s.word(1371, 1) == -1);
        assert!(on_update(1371, &mut s, false).is_empty());
        // Gate 4 is next (region 1379); with object 1 animating it stays shut.
        s.animating.insert(1);
        assert!(on_trigger(1371, 2, enter(4), &mut s).actions.is_empty());
        s.animating.clear();
        assert!(on_trigger(1371, 2, enter(4), &mut s).actions.contains(&Action::LoadRegion { slot: 0, region: Some(1379) }));
        // All three won: Z1 sets 345 and 100 and opens Z0, which posts the won result.
        s.set(343, true);
        s.set(344, true);
        on_trigger(1371, 1, enter(1), &mut s);
        assert!(s.flag(345) && s.flag(100));
        s.set_word(1371, 3, 1);
        assert_eq!(on_trigger(1371, 0, enter(0), &mut s).actions, vec![Action::ReplaceExterior { slot: 157, plane: 0 }]);
        assert_eq!(s.blackboard.get(&(1, 157)), Some(&1));
    }

