    #[test]
    fn module_1397_room() {
        let mut s = GameState::default();
        let init = on_init(1397, &mut s);
        assert!(init.contains(&Action::RegisterTrigger { index: 21, routine: 21 }) && init.contains(&Action::MoveEntity { entity: 6, locator: 78, face: true }));
        let at = |i, square| TriggerCall { index: i, state: 1, object: true, square, block: -1 };
        // The plate lift scene (handler G): a hero's fire and block 1 on plate 11 do nothing;
        // block 3 there raises lift 29, swaps in floor 33 and places blocks 2, 1 and 3 again.
        let plate = |b| TriggerCall { index: 11, state: 1, object: true, square: false, block: b };
        assert!(on_trigger(1397, 9, plate(-1), &mut s).actions.is_empty());
        assert!(on_trigger(1397, 9, plate(1), &mut s).actions.is_empty());
        let scene = on_trigger(1397, 9, plate(3), &mut s).actions;
        assert!(scene.contains(&Action::PlayAnim { obj: 29, speed: 0.2, wait: false }) && scene.contains(&Action::InitObjOn { obj: 33, end: false }));
        let order: Vec<usize> = scene.iter().filter_map(|a| if let Action::ReacquireBlock { block, ceiling } = a { assert_eq!(*ceiling, 3.0); Some(*block) } else { None }).collect();
        assert_eq!(order, vec![2, 1, 3]);
        assert!(on_trigger(1397, 9, plate(3), &mut s).actions.is_empty(), "busy while the scene runs");
        s.set_word(1397, 43, 0);
        assert!(on_trigger(1397, 9, plate(3), &mut s).actions.is_empty(), "plate 11 runs once");
        // The spec's button vector: 2, 1, 4, 3, 6: AI 0 at 19, AI 1 at 18; 699 after the 6.
        let presses: Vec<Vec<Action>> = [2, 1, 4, 3, 6].into_iter().map(|i| on_trigger(1397, 1, at(i, true), &mut s).actions).collect();
        assert!(presses[0].contains(&Action::MoveEntity { entity: 0, locator: 19, face: true }) && presses[2].contains(&Action::MoveEntity { entity: 1, locator: 18, face: true }));
        assert!(s.flag(699) && presses[4].contains(&Action::DeactivateObj { obj: 8 }));
        assert!(on_trigger(1397, 1, at(2, true), &mut s).actions.is_empty());
        // Statues: presses 0, 3, 2 and 1 on triggers 17 to 20, turned by the thread, then K21.
        for (k, n) in [0, 3, 2, 1].into_iter().enumerate() {
            for _ in 0..n {
                on_trigger(1397, 17 + k as u8, at(17 + k as u16, true), &mut s);
            }
        }
        on_trigger(1397, 21, at(21, false), &mut s);
        assert!(!s.flag(700));
        for t in 0..300 {
            s.hero.tick = t;
            on_update(1397, &mut s, false);
        }
        on_trigger(1397, 21, at(21, false), &mut s);
        assert!(s.flag(700) && s.word(1397, 23) == -3160);
        assert!(on_update(1397, &mut s, false).contains(&Action::ObjOffset { obj: 41, y: 25.1 }));
        // T0: a block's first fire solves the room once.
        let block = TriggerCall { index: 0, state: 1, object: false, square: false, block: 1 };
        assert!(on_trigger(1397, 50, block, &mut s).actions.contains(&Action::ActivateBlock { block: 1, on: false }));
        assert!(s.flag(687) && on_trigger(1397, 50, block, &mut s).actions.is_empty());
        // The arrival: 60 -> locator 1, read once.
        s.blackboard.insert((2, 173), 60);
        assert_eq!(on_activate(1397, &mut s), vec![Action::MoveHero { locator: 1 }]);
        assert_eq!(on_activate(1397, &mut s), vec![Action::ReturnCamera { preset: -1, release: true }]);
    }

    #[test]
    fn module_1091_sequencers() {
        // Trigger 42 starts mode 1 (object 6 first, then the steps); trigger 41 cancels it (6
        // and 9 back) and mode 2 swings object 3.
        let mut s = GameState::default();
        let enter = |index| TriggerCall { index, state: 1, object: true, square: false, block: -1 };
        on_trigger(1091, 41, enter(42), &mut s);
        let a = on_update(1091, &mut s, false);
        assert_eq!(a[0], Action::PlayAnim { obj: 6, speed: 1.6, wait: true });
        assert!(a.contains(&Action::Bits { word: 50, set: 1, clear: 0 }) && on_update(1091, &mut s, false).is_empty(), "one pass at a time");
        s.set_word(1091, 52, 0);
        on_trigger(1091, 41, enter(41), &mut s);
        let a = on_update(1091, &mut s, false);
        assert_eq!(a[0], Action::PlayAnim { obj: 6, speed: -0.4, wait: true });
        s.set_word(1091, 52, 0);
        assert_eq!(on_update(1091, &mut s, false)[0], Action::PlayAnim { obj: 3, speed: 0.6, wait: true });
        // A flag object kills while its flag is set.
        s.set_word(1091, 50, 1);
        let mut t = GameState::default();
        t.set_word(1091, 45, 1);
        let touch = TriggerCall { index: 0, state: 1, object: true, square: false, block: -1 };
        assert!(on_trigger(1091, 15, touch, &mut t).actions.contains(&Action::KillHero));
    }

    #[test]
    fn module_1091_hazards() {
        let mut s = GameState::default();
        let init = on_init(1091, &mut s);
        assert!(init.contains(&Action::RegisterAnimTrigger { host: 7, index: 0, routine: 17 }) && init.contains(&Action::RegisterTrigger { index: 43, routine: 41 }));
        let touch = |i| TriggerCall { index: i, state: 1, object: true, square: false, block: -1 };
        // TV-A1: object 6 damages 2, then 0.5 s; a run at a time.
        assert_eq!(on_trigger(1091, 16, touch(0), &mut s).actions, vec![Action::DamageHero { amount: 2 }, wait(0.5), Action::Bits { word: 16, set: 0, clear: 1 }]);
        assert!(on_trigger(1091, 16, touch(0), &mut s).actions.is_empty());
        // Object 7 kills: the hero then moves to locator 6.
        assert_eq!(&on_trigger(1091, 17, touch(0), &mut s).actions[..3], &[Action::KillHero, wait(1.0), Action::MoveHero { locator: 6 }]);
        // TV-B1: trigger 43 sweeps 36 to 40 at 5.0, then 2 damage and poison, once per visit.
        let out = on_trigger(1091, 41, touch(43), &mut s).actions;
        let swept: Vec<usize> = out.iter().filter_map(|a| if let Action::PlayAnim { obj, speed, .. } = a { (*speed == 5.0).then_some(*obj) } else { None }).collect();
        assert_eq!(swept, vec![36, 37, 38, 39, 40]);
        assert!(out.contains(&Action::DamageHero { amount: 2 }) && out.contains(&Action::HeroStatus { code: 2, seconds: -1 }) && out.contains(&Action::SetObjTime { obj: 16, seconds: 10.0 / 30.0 }));
        assert!(on_trigger(1091, 41, touch(43), &mut s).actions.is_empty());
    }

