    #[test]
    fn hero_swap_scene_1244() {
        let mut s = GameState::default();
        let init = on_init(1244, &mut s);
        assert!(s.flag(271));
        assert_eq!(init.len(), 9, "four objects off, five registrations");
        let call = TriggerCall { index: 0, state: 1, object: true, square: false, block: -1 };
        // Not in swap mode 2: no scene.
        s.hero.swap_mode = 1;
        assert!(on_trigger(1244, 1, call, &mut s).actions.is_empty());
        s.hero.swap_mode = 2;
        let a = on_trigger(1244, 1, call, &mut s).actions;
        assert!(a.contains(&Action::ActivateHero { hero: 1, locator: 16, block: false, fade: false, cue: false }));
        assert_eq!(a.last(), Some(&Action::SwapMode { mode: 1 }));
        // The break scene ends on Tor in mode 0 and sets 272, which closes triggers 0, 3 and 4.
        let b = on_trigger(1244, 5, TriggerCall { index: 3, ..call }, &mut s).actions;
        let mode = b.iter().position(|x| *x == Action::SwapMode { mode: 0 }).unwrap();
        assert_eq!(b[mode + 1], Action::ActivateHero { hero: 0, locator: 12, block: false, fade: false, cue: false });
        assert!(b.contains(&Action::SetFlag { flag: 272, on: true }));
        s.set(272, true);
        assert!(on_trigger(1244, 1, call, &mut s).actions.is_empty());
        assert!(on_trigger(1244, 4, TriggerCall { index: 4, ..call }, &mut s).actions.is_empty());
        // Trigger 4 runs once per level-state 0.
        s.set(272, false);
        assert!(!on_trigger(1244, 4, TriggerCall { index: 4, ..call }, &mut s).actions.is_empty());
        assert!(on_trigger(1244, 4, TriggerCall { index: 4, ..call }, &mut s).actions.is_empty());
    }

    #[test]
    fn miamice_game() {
        // SPEC-0045 1163: the keeper with 632 starts the game (line 8, flag 156, level state 0,
        // the catch on); deliveries 1 to 4 show lines 43 to 46 once each; level state 5 wins
        // (158 and 23, the keeper's line 4). A return with 156 set and 158 clear restarts.
        let mut s = GameState::default();
        s.set(632, true);
        let r = proximity_routine(1163, 10).unwrap();
        let start = on_talk(1163, r, &mut s);
        assert!(start.contains(&Action::Talk { line: 8 }) && start.contains(&Action::MiamouseInit { field: 0, cage: 1 }) && s.flag(156));
        for n in 1..=4u16 {
            s.level_flags = [n].into();
            assert_eq!(on_update(1163, &mut s, false), vec![Action::Message { line: 42 + n }]);
            assert!(on_update(1163, &mut s, false).is_empty(), "once each");
        }
        s.level_flags = [5].into();
        assert_eq!(on_update(1163, &mut s, false), vec![Action::Converse { entity: 0, line: 4 }]);
        assert!(s.flag(158) && s.flag(23));
        let mut s = GameState::default();
        s.set(156, true);
        assert!(on_activate(1163, &mut s).contains(&Action::MiamouseInit { field: 0, cage: 1 }));
        s.set(158, true);
        assert!(on_activate(1163, &mut s).contains(&Action::MiamouseDisable));
        assert!(on_init(1163, &mut s).contains(&Action::LoadRegion { slot: 0, region: Some(1164) }));
    }

    #[test]
    fn courtyard_lessons() {
        // SPEC-0044 1056. Chain lesson: Init with 22 picks trainer entity 5 and loads 1057 and
        // 1064; in talk zone 10 the auto-talk shows lines 58 to 60 (flag 154).
        let mut s = GameState::default();
        s.set(22, true);
        let init = on_init(1056, &mut s);
        assert!(init.contains(&Action::LoadRegion { slot: 0, region: Some(1057) }) && init.contains(&Action::LoadRegion { slot: 1, region: Some(1064) }));
        let zone = |s: &mut GameState, i: u16| on_trigger(1056, 5, TriggerCall { index: i, state: 1, object: true, square: false, block: -1 }, s);
        zone(&mut s, 10);
        assert_eq!(on_update(1056, &mut s, false), vec![Action::Converse { entity: 5, line: 58 }]);
        assert!(s.flag(154));
        // In the chain area, a finisher (attack state 4) that misses entity 4 gives remark 5
        // (lines 42, 41, 40), spoken once no attack is active.
        zone(&mut s, 5);
        s.hero.sub = 4;
        on_update(1056, &mut s, false);
        zone(&mut s, 5);
        s.hero.sub = 0;
        assert_eq!(on_update(1056, &mut s, false), vec![Action::Converse { entity: 5, line: 42 }]);
        // A finisher hitting entity 4 sets 155; the talk waits for zone 10.
        s.hero.sub = 4;
        s.hero.hits = vec![4];
        assert!(on_update(1056, &mut s, false).is_empty() && s.flag(155));
        s.hero = HeroView::default();
        zone(&mut s, 10);
        assert_eq!(on_update(1056, &mut s, false), vec![Action::Converse { entity: 5, line: 36 }]);
        assert!(s.flag(632));
        // Spin lesson: one spin (state 7) marking entities 7, 8 and 9 sets 161.
        let mut s = GameState::default();
        for f in [22, 23, 160] {
            s.set(f, true);
        }
        on_init(1056, &mut s);
        for e in [7, 8, 9] {
            s.hero = HeroView { sub: 7, hits: vec![e], ..HeroView::default() };
            on_update(1056, &mut s, false);
        }
        assert!(s.flag(161));
        // Mote lesson: with 169 set, holding item 160 sets 170; a fire Mote in word 2 sets 171.
        let mut s = GameState::default();
        for f in [22, 24, 169] {
            s.set(f, true);
        }
        on_init(1056, &mut s);
        // The lesson slot's placement 0, once per load after the slot arrives.
        let item = Action::ItemActivate { slot: 0, ordinal: 0, snap: false, placed: true };
        assert!(!on_update(1056, &mut s, false).contains(&item));
        s.slot_alive.insert(0, 0);
        assert!(on_update(1056, &mut s, false).contains(&item));
        assert!(!on_update(1056, &mut s, false).contains(&item));
        s.give(160, 100);
        on_update(1056, &mut s, false);
        assert!(s.flag(170));
        s.hero.attack_mote = Some(160);
        on_update(1056, &mut s, false);
        assert!(s.flag(171));
        assert_eq!(undamageable(1056), &[4, 7, 8, 9, 20, 21, 14]);
    }

    #[test]
    fn module_990_prompts() {
        // SPEC-0042 990 handler P test vector: object 12 inactive, the hero in trigger 3: context
        // 1 and a press swaps 12/13 and plays track 5; afterwards nothing; trigger 7 shows
        // context 4 every tick and a press turns the lever word from -1 to 1.
        let mut s = GameState::default();
        let v = on_init(990, &mut s);
        assert!(v.contains(&Action::InitObjOn { obj: 13, end: true }) && v.contains(&Action::RegisterTrigger { index: 7, routine: 3 }));
        let at = |index, square| TriggerCall { index, state: 2, object: true, square, block: -1 };
        assert_eq!(on_trigger(990, 3, at(3, false), &mut s).prompt, Some(1));
        let a = on_trigger(990, 3, at(3, true), &mut s).actions;
        assert!(a.contains(&Action::InitObjOn { obj: 12, end: false }) && a.contains(&Action::PlayCamera { track: 5, wait: true, end: 1, speed: 1.0 }));
        let after = on_trigger(990, 3, at(3, true), &mut s);
        assert!(after.prompt.is_none() && after.actions.is_empty());
        assert_eq!(on_trigger(990, 3, at(7, false), &mut s).prompt, Some(4));
        let lever = on_trigger(990, 3, at(7, true), &mut s).actions;
        assert!(lever.contains(&Action::PlayAnim { obj: 0, speed: 1.0, wait: false }));
    }

    #[test]
    fn castle_story_triggers() {
        // SPEC-0045 1098 triggers 5, 4, 6 and 10.
        let mut s = GameState::default();
        assert!(on_init(1098, &mut s).contains(&Action::RegisterTrigger { index: 10, routine: 10 }));
        let enter = |index| TriggerCall { index, state: 1, object: true, square: false, block: -1 };
        assert!(on_trigger(1098, 4, enter(4), &mut s).actions.is_empty(), "trigger 4 waits for 203");
        let a = on_trigger(1098, 5, enter(5), &mut s).actions;
        assert!(s.flag(203) && s.flag(151) && a.contains(&Action::PlayFmv { movie: 8 }));
        let b = on_trigger(1098, 4, enter(4), &mut s).actions;
        assert!(s.flag(204) && b.contains(&Action::PlayFmv { movie: 9 }) && b.contains(&Action::LoadRegion { slot: 0, region: Some(1105) }));
        s.set(216, true);
        assert_eq!(on_trigger(1098, 6, enter(6), &mut s).actions.last(), Some(&Action::ReplaceExterior { slot: 127, plane: -1 }));
        assert!(on_trigger(1098, 6, enter(6), &mut s).actions.is_empty());
        // Trigger 10 acts on every fourth pass.
        s.set(193, true);
        let runs: Vec<bool> = (0..4).map(|_| !on_trigger(1098, 10, enter(10), &mut s).actions.is_empty()).collect();
        assert_eq!(runs, [false, false, false, true]);
        assert!(s.flag(194));
        // Switch 18 (R-0113): with 162 clear a press shows line 18; with 162 set and 167 clear it
        // swaps object 17 for 18 once (camera 7, hero animation 0). Switch 20 needs stage 31.
        let press = |index| TriggerCall { index, state: 2, object: true, square: true, block: -1 };
        assert_eq!(on_trigger(1098, 18, press(18), &mut s).actions, vec![Action::Message { line: 18 }]);
        s.set(162, true);
        let a = on_trigger(1098, 18, press(18), &mut s).actions;
        assert!(a.contains(&Action::WalkHero { locator: 101, wait: true, orient: true }) && a.contains(&Action::InitObjOn { obj: 18, end: false }));
        assert!(a.contains(&Action::HeroAnim { anim: 0, wait: false }));
        assert!(on_trigger(1098, 18, press(18), &mut s).actions.is_empty());
        assert_eq!(on_trigger(1098, 20, press(20), &mut s).actions, vec![Action::Message { line: 18 }]);
        s.set(31, true);
        assert!(on_trigger(1098, 20, press(20), &mut s).actions.contains(&Action::InitObjOn { obj: 22, end: false }));
    }

